PRINT ('Migra tabella: Messaggi_da_Agronica')
IF NOT EXISTS (select 1 from sys.tables tt where tt.name = 'Messaggi_da_Agronica' )
BEGIN
    CREATE TABLE [dbo].[Messaggi_da_Agronica](
        [ID] [int] NOT NULL,
        [ID_Sito] [int] NULL,
        [Messaggio] [nvarchar](max) NULL,
        [inviato] [smallint] NULL,
        [datainvio] [datetime] NULL,
        [Data_Creazione] [datetime] NULL,
        [Data_Modifica] [datetime] NULL,
        [Username_Creazione] [varchar](250) NULL,
        [Username_Modifica] [varchar](250) NULL,
        [Validita_Inizio] [datetime] NULL,
        [Validita_Fine] [datetime] NULL
    CONSTRAINT [PK_Messaggi_da_Agronica] PRIMARY KEY CLUSTERED 
    (
        [ID] ASC
    )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
    ) ON [PRIMARY]
END
GO

PRINT ('Migra tabella: Messaggi_da_Agronica_XLingue')
IF NOT EXISTS (select 1 from sys.tables tt where tt.name = 'Messaggi_da_Agronica_XLingue' )
BEGIN
    CREATE TABLE [dbo].[Messaggi_da_Agronica_XLingue](
        [ID_Messaggio] [int] NOT NULL,
        [Lingua_Cod] [int] NOT NULL,
        [Messaggio] [nvarchar](max) NOT NULL,
        [inviato] [smallint] NULL DEFAULT ((0)),
        [datainvio] [datetime] NULL,
        [Data_Creazione] [datetime] NULL DEFAULT (getdate()),
        [Data_Modifica] [datetime] NULL DEFAULT (getdate()),
        [Username_Creazione] [varchar](250) NULL  DEFAULT ('agronica'),
        [Username_Modifica] [varchar](250) NULL DEFAULT ('agronica'),
        [Validita_Inizio] [datetime] NULL   DEFAULT ('01/01/1900'),
        [Validita_Fine] [datetime] NULL   DEFAULT ('31/12/2100'),
        CONSTRAINT [PK_Messaggi_da_Agronica_XLingue] PRIMARY KEY CLUSTERED 
        (
            [ID_Messaggio] ASC,
            [Lingua_Cod] ASC
        )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
    ) ON [PRIMARY]
END
GO

PRINT ('Tabella Configurazione_Servizi: Aggiunte date indisponibilita')
IF NOT EXISTS (select 1 from sys.tables tt inner join sys.columns cc on tt.object_id = cc.object_id 
where tt.name = 'Configurazione_Servizi' and cc.name = 'Data_Inizio_Indisponibilita')
begin
  alter table Configurazione_Servizi add  Data_Inizio_Indisponibilita [datetime] NULL DEFAULT '1900-01-01' WITH VALUES
end
GO

IF NOT EXISTS (select 1 from sys.tables tt inner join sys.columns cc on tt.object_id = cc.object_id 
where tt.name = 'Configurazione_Servizi' and cc.name = 'Data_Fine_Indisponibilita')
begin
