PRINT ('Migra tabella: Utenti_Token_JWT')
IF NOT EXISTS (select 1 from sys.tables tt where tt.name = 'Utenti_Token_JWT' )
BEGIN
    CREATE TABLE [dbo].[Utenti_Token_JWT](
        [idToken] [varchar](500) NOT NULL,
        [objP_SuperServer] [varchar](MAX) NULL,
        [objP_Server] [varchar](MAX) NULL,
        [objP_Utenti] [varchar](MAX) NULL,
        [Codice_Fiscale] [varchar](250) NOT NULL,
        [CoreWSBaseURL] [varchar](250) NULL DEFAULT (''),
        [Username] [varchar](250) NULL DEFAULT (''),
        [PivaSuperUser] [varchar](250) NOT NULL,
        [VersioneApp] [varchar](250) NULL DEFAULT (''),
        [refreshToken] [varchar](MAX) NULL DEFAULT (''),
        [inviato] [smallint] NULL DEFAULT (0),
        [datainvio] [datetime] NULL,
        [Data_Creazione] [datetime] NULL DEFAULT (getdate()),
        [Data_Modifica] [datetime] NULL DEFAULT (getdate()),
        [Username_Creazione] [varchar](250) NULL DEFAULT ('agronica'),
        [Username_Modifica] [varchar](250) NULL DEFAULT ('agronica'),
        [Validita_Inizio] [datetime] NULL DEFAULT ('01/01/1900'),
        [Validita_Fine] [datetime] NULL DEFAULT ('31/12/2100'),
        CONSTRAINT [PK_Utenti_Token_JWT] PRIMARY KEY CLUSTERED 
        (
              [idToken] ASC
        )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
    ) ON [PRIMARY]
END
