    --Assegno il nuovo permesso a tutti quelli che avevano il 278
    INSERT INTO Utenti_Permessi
    SELECT 
        up1.UserName
        , up1.Id_Servizio
        , Id_Attivita = 486
        , up1.Id_Operazione
        , up1.ID
        , up1.Inizio_Ore
        , up1.Inizio_Minuti
        , up1.Fine_Ore
        , up1.Fine_Minuti
        , up1.inviato
        , up1.datainvio
        , up1.Data_Creazione
        , up1.Data_Modifica
        , up1.Username_Creazione
        , up1.Username_Modifica
        , up1.Validita_Inizio
        , up1.Validita_Fine
        , up1.Tipologia_Cod
    FROM  Utenti_Permessi up1
    LEFT JOIN (
        SELECT username, id_servizio, id_attivita, id_operazione, id FROM utenti_permessi WHERE id_attivita = 486
    ) up2 ON 
        up2.UserName = up1.UserName 
        AND up2.Id_Servizio = up1.Id_Servizio 
        AND up2.Id_Operazione = up1.Id_Operazione
        AND up2.ID = up1.id
    WHERE up1.Id_Attivita = 278  
    AND up2.id_attivita is null



    INSERT INTO Utenti_TipologiexPermessi
    SELECT
        Piva_SuperUser
        , Tipologia_Cod
        , Id_Servizio
        , Id_Attivita = 486
        , Id_Operazione
        , inviato
        , datainvio
        , Data_Creazione
        , Data_Modifica
        , Username_Creazione
        , Username_Modifica
        , Validita_Inizio
        , Validita_Fine
    FROM Utenti_TipologiexPermessi
    WHERE Id_Attivita = 278



END
