-- Tabella Utenti: aumento dimensione campo password
IF EXISTS (select 1 from sys.tables tt 
inner join sys.columns cc on tt.object_id = cc.object_id 
where tt.name = 'Utenti' 
  and cc.name = 'Password'
  and cc.max_length < 128)
alter table [dbo].[Utenti] alter column [Password] varchar(128) null
