declare @PivaSuperUser as nvarchar(25)
set @PivaSuperUser = (SELECT  top 1 [USER] FROM $(ServerDB).dbo.utentiximprese)
declare @SuperUserUsername varchar(1000)
set @SuperUserUsername = (SELECT  top 1 [Utente_Profilo] FROM $(UtentiDB).dbo.Utenti_Profili Where [Utente] = [Utente_Profilo])

IF EXISTS (select 1 from sys.tables tt  where tt.name = 'Cliente_Permessi') AND NOT EXISTS (select 1 from Cliente_Permessi)
BEGIN
   ; with permessi_totali_cte as (
        select Utenti_TipologiexPermessi.Id_Servizio, Utenti_TipologiexPermessi.Id_Attivita, Utenti_TipologiexPermessi.Id_Operazione from Utenti_TipologiexPermessi 
        union -- esegue già una distinct dei valori
        select Utenti_Permessi.Id_Servizio, Utenti_Permessi.Id_Attivita, Utenti_Permessi.Id_Operazione from Utenti_Permessi 
    )
    insert into Cliente_Permessi --(PivaSuperUser, UserName, Id_Servizio, Id_Attivita, max(Id_Operazione), inviato, Username_Creazione, Username_Modifica)
    select @PivaSuperUser as PivaSuperUser, 
        @SuperUserUsername as UserName, 
        Id_Servizio, 
        Id_Attivita, 
        MAX(Id_Operazione), 
        1 as inviato, 
        null as datainvio, 
        GETDATE() as Data_Creazione, 
        GETDATE() as Data_Modifica, 
        'agronica' as Username_Creazione, 
        'agronica' as Username_Modifica, 
        CONVERT(datetime, '1900-01-01 00:00:00.000', 120) as Validita_Inizio, 
        CONVERT(datetime, '2100-12-31 00:00:00.000', 120) as Validita_Fine
    from permessi_totali_cte
    group by Id_Attivita, Id_Servizio
END
GO


