    DECLARE @PK_CONSTRAINT VARCHAR(50)
    SET @PK_CONSTRAINT = (SELECT ISNULL(CONSTRAINT_NAME,'')
                          FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS t
                          WHERE TABLE_NAME = 'Utenti_Viste' 
                          AND CONSTRAINT_TYPE = 'PRIMARY KEY')

     IF (@PK_CONSTRAINT <> '')
     BEGIN
        EXEC('ALTER TABLE Utenti_Viste DROP CONSTRAINT ' + @PK_CONSTRAINT)
     END

     ALTER TABLE Utenti_Viste ADD 
        CONSTRAINT [PK_Utenti_Viste] PRIMARY KEY  
        (
            [IdVista],
            [NomeUtente],
            [GridId]
        )  ON [PRIMARY] 


   ALTER TABLE  [dbo].[Utenti_Viste] DROP COLUMN [NomeComponente]

END
