declare @SuperUserUsername varchar(1000)
set @SuperUserUsername = (SELECT  top 1 [Utente_Profilo] FROM [dbo].[Utenti_Profili] Where [Utente] = [Utente_Profilo]) 

IF EXISTS (SELECT 1 FROM [dbo].[Utenti_Permessi] WHERE  [dbo].[Utenti_Permessi].Id_Attivita = 285 AND NOT 
            [dbo].[Utenti_Permessi].Username = @SuperUserUsername) AND
   EXISTS (SELECT 1 FROM $(ServerDB).[dbo].[Configurazione_Siti] where chiave = 'OperazioniAgendaNG' and valore = 'true') BEGIN

    print('Elimino i permessi alla pagina delle vecchie Visite e inserisco i permessi per la pagina Visite NG');

    INSERT INTO  [dbo].[Utenti_Permessi] ([Username],[Id_Servizio],[Id_Attivita],[ID_Operazione],
    [ID],[Inizio_Ore],[Inizio_Minuti],[Fine_Ore],[Fine_Minuti],[Data_Creazione],[Data_Modifica],
    [Username_Creazione],[Username_Modifica],[Validita_Inizio],[Validita_Fine],[Tipologia_Cod])

    SELECT UT_P_2.Username,UT_P_2.Id_Servizio,515,UT_P_2.ID_Operazione,
    UT_P_2.ID,UT_P_2.Inizio_Ore,UT_P_2.Inizio_Minuti,UT_P_2.Fine_Ore,UT_P_2.Fine_Minuti,GETDATE(),GETDATE(),
    UT_P_2.Username_Creazione,UT_P_2.Username_Modifica,UT_P_2.Validita_Inizio,UT_P_2.Validita_Fine,UT_P_2.Tipologia_Cod

    FROM [dbo].[Utenti_Permessi] UT_P_2
    WHERE UT_P_2.Id_Attivita = 285
    AND NOT EXISTS
     (
        SELECT *
        FROM [dbo].[Utenti_Permessi] UT_P_3
        WHERE UT_P_3.UserName = UT_P_2.UserName and
        UT_P_3.Id_Servizio = UT_P_2.Id_Servizio and
        UT_P_3.Id_Operazione = UT_P_2.Id_Operazione and
        UT_P_3.ID = UT_P_2.ID and
        UT_P_3.Id_Attivita = 515 
    )

    DELETE [dbo].[Utenti_Permessi] WHERE  [dbo].[Utenti_Permessi].Id_Attivita = 285 AND NOT 
     [dbo].[Utenti_Permessi].Username = @SuperUserUsername
END
GO

