    [Data_Creazione] [datetime] NULL DEFAULT (getdate()),
    [Data_Modifica] [datetime] NULL DEFAULT (getdate()),
    [Username_Creazione] [varchar](250) NULL  DEFAULT ('agronica') ,
    [Username_Modifica] [varchar](250) NULL  DEFAULT ('agronica') ,
