END
GO

IF NOT EXISTS (select 1 from sys.tables tt 
    inner join sys.columns cc on tt.object_id = cc.object_id
    where tt.name = 'SistemiEsterni_RicezioneNotifiche'
    and cc.name = 'EsitoText')
BEGIN
    PRINT('non esiste la colonna EsitoText nella tabella SistemiEsterni_RicezioneNotifiche la creo')
    ALTER TABLE [dbo].[SistemiEsterni_RicezioneNotifiche] ADD EsitoText varchar(max) NULL DEFAULT('') WITH VALUES

END
ELSE

    IF EXISTS (select 1 from sys.tables tt 
    inner join sys.columns cc on tt.object_id = cc.object_id
    where tt.name = 'SistemiEsterni_RicezioneNotifiche'
    and cc.name = 'EsitoText' and cc.max_length<>-1)
        BEGIN
            PRINT('trovata la colonna EsitoText nella tabella SistemiEsterni_RicezioneNotifiche ma di formato diverso, la ricreo')
            
            declare @k_sql as varchar(200)
            select @k_sql = 'ALTER TABLE [dbo].[SistemiEsterni_RicezioneNotifiche] drop constraint [' +  kk.name +']' from sys.tables tt 
                inner join sys.columns cc on tt.object_id = cc.object_id
                inner join sys.default_constraints kk on kk.parent_column_id=cc.column_id and tt.object_id=kk.parent_object_id
                where tt.name = 'SistemiEsterni_RicezioneNotifiche'
                and cc.name = 'EsitoText'

            EXEC (@k_sql)
            
            ALTER TABLE [dbo].[SistemiEsterni_RicezioneNotifiche] DROP COLUMN EsitoText
            ALTER TABLE [dbo].[SistemiEsterni_RicezioneNotifiche] ADD EsitoText varchar(max) NULL DEFAULT('') WITH VALUES
        END
GO


