if not exists (select 1 from sys.columns c inner join sys.tables t on t.object_id = c.object_id where t.name = 'GIS_ElementiGrafici' and c.name = 'Poligono_GeoEntity_WKT') 
begin
    
    PRINT ('GIS_ElementiGrafici, nuova colonna con WKT memorizzato (Poligono_GeoEntity_WKT)')
    -- 2000 is from here: https://www.sqlshack.com/varcharmax-data-type-walkthrough-and-its-comparison-with-varcharn-in-sql-server/
    alter table GIS_ElementiGrafici add Poligono_GeoEntity_WKT varchar(2000)

end

IF NOT EXISTS (SELECT 1 FROM sys.triggers WHERE Name = 'TRG_GIS_ElementiGrafici_WKT')
BEGIN
EXEC dbo.sp_executesql @statement = N'
       CREATE TRIGGER [dbo].[TRG_GIS_ElementiGrafici_WKT]
       ON [dbo].[GIS_ElementiGrafici]
       AFTER INSERT, UPDATE
       AS
       BEGIN
             If UPDATE(Poligono_GeoEntity)
             BEGIN
                    merge into GIS_ElementiGrafici dest using
                        (SELECT Entita_Cod,Poligono_GeoEntity.STAsText() as wkt, len(Poligono_GeoEntity.STAsText()) as wkt_len from Inserted) source
                        on dest.Entita_Cod=source.Entita_Cod
                        when matched THEN
                            UPDATE SET Poligono_GeoEntity_WKT = CASE WHEN source.wkt_len<=2000 then source.wkt ELSE NULL END;
             END
       END'

       declare @sql_major_version as integer = cast(SERVERPROPERTY('productmajorversion') as integer)

       if (@sql_major_version>=15)
       BEGIN
           PRINT('AGGIORNAMENTO MASSIVO POLIGONO_WKT')
            DECLARE @stepmax AS integer
            DECLARE @step AS integer
            DECLARE @row_number AS integer

            set @step= 0
            set @row_number=5000
            set @stepmax = (select count(Entita_Cod) from GIS_ElementiGrafici)

            while @step<=@stepmax
            begin
            begin try
                PRINT('update Poligono_GeoEntity_WKT start from' + cast(@step as varchar))
                exec('update GIS_ElementiGrafici SET Poligono_GeoEntity=Poligono_GeoEntity where Entita_Cod in
                (select Entita_Cod from GIS_ElementiGrafici order by Entita_Cod offset '+@step+' rows fetch next '+@row_number+' rows only)')
                set @step=@step+@row_number
            end try
            begin catch
                    SELECT ERROR_MESSAGE() AS ErrorMessage;
              END CATCH
            end
        END
        else
        BEGIN
            PRINT('AGGIORNAMENTO MASSIVO POLIGONO_WKT NON PERMESSO VERSIONE SQL INFERIORE A SQL SERVER 2012')
        END
END
GO

