IF not exists (select 1 from sys.databases where name='$(ServerDB)' and compatibility_level>=140)
    begin
        PRINT('Database con livello di compatibilita minore di 140, verifico gli indici spatial nella vecchia modalita')
        IF (NOT EXISTS (select 1 from sys.indexes id where id.name = 'AgroIndex_GIS_ElementiGrafici_SpatialIndex-16-MMMM'  ) )
        BEGIN
            CREATE SPATIAL INDEX [AgroIndex_GIS_ElementiGrafici_SpatialIndex-16-MMMM] ON [dbo].[GIS_ElementiGrafici]
            (
                [Poligono_GeoEntity]
            )USING  GEOGRAPHY_GRID 
            WITH (GRIDS =(LEVEL_1 = MEDIUM,LEVEL_2 = MEDIUM,LEVEL_3 = MEDIUM,LEVEL_4 = MEDIUM), 
            CELLS_PER_OBJECT = 16, PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, DROP_EXISTING = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
        END
    END
ELSE
    BEGIN
        PRINT('Database con livello di compatibilita maggiore o uguale di 140, verifico gli indici spatial nella nuova modalita')
        IF NOT EXISTS (select 1 from sys.indexes id where id.name = 'AgroIndex_GIS_ElementiGrafici_SpatialIndex-16-Auto'  )
        BEGIN
            CREATE SPATIAL INDEX [AgroIndex_GIS_ElementiGrafici_SpatialIndex-16-Auto] ON [dbo].[GIS_ElementiGrafici]
            (
                [Poligono_GeoEntity]
            )USING  GEOGRAPHY_AUTO_GRID with (
            CELLS_PER_OBJECT = 16, PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, DROP_EXISTING = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
        END
        IF EXISTS (select 1 from sys.indexes id where id.name = 'AgroIndex_GIS_ElementiGrafici_SpatialIndex-16-MMMM'  )
        BEGIN
            DROP INDEX [AgroIndex_GIS_ElementiGrafici_SpatialIndex-16-MMMM] ON [dbo].[GIS_ElementiGrafici] 
        END
    END
GO

