           ,[inviato],[datainvio],[Data_Creazione],[Data_Modifica],[Username_Creazione],[Username_Modifica],[Validita_Inizio],[Validita_Fine])
     VALUES
           (@PivaSuperUser, '', 214, 0, 0, 'FR', 1  , 'Passeport Phytosanitaire',
           0, NULL, getdate(),getdate(),@PivaSuperUser,@PivaSuperUser,'01/01/1900','31/12/2100' )
