        else 0 end
        from Sequenza_Tabelle where Nome_Tabella = 'PUA_Effluente')
if @SEQ_TAB_EXIST = 0
    begin 

        UPDATE d SET id = r.r
        FROM PUA_Effluente d
        INNER JOIN (
            SELECT piva_superuser,pua_cod,regolamento_cod,eff_cod
                , r = DENSE_RANK() OVER(order by  piva_superuser,pua_cod,regolamento_cod,eff_cod )
            FROM PUA_Effluente
        ) r ON d.piva_superuser = r.piva_superuser
        and d.pua_cod = r.pua_cod
        and d.regolamento_cod = r.regolamento_cod
        and d.eff_cod = r.eff_cod

        alter table PUA_Effluente ALTER COLUMN ID int NOT NULL

       ALTER TABLE [dbo].[PUA_Effluente] DROP CONSTRAINT [PK_PUA_Effluente]

       alter table [dbo].[PUA_Effluente] ADD  CONSTRAINT [PK_PUA_Effluente] PRIMARY KEY CLUSTERED 
       (
             [Piva_SuperUser] ASC,
             [ID] ASC
       )
       ON [PRIMARY]

       set @MAX = (select coalesce( max(Id),0)  from PUA_Effluente)
        INSERT INTO Sequenza_Tabelle 
            (Nome_Tabella,Ultimo_Valore,Base,[End] ,inviato ,datainvio ,Data_Creazione ,Data_Modifica,Username_Creazione,Username_Modifica)
            VALUES
            ('PUA_Effluente',@MAX,0,2000000000,0,null,GETDATE(),GETDATE(),'script','script')
    end

GO


PRINT ('Tabella Alert_Area: Aggiunta TipoEntita_Cod_Secondario')
IF NOT EXISTS (select 1 from sys.tables tt inner join sys.columns cc on tt.object_id = cc.object_id 
where tt.name = 'Alert_Area' and cc.name = 'TipoEntita_Cod_Secondario')
begin
  alter table Alert_Area add  TipoEntita_Cod_Secondario [int] NULL DEFAULT 0 WITH VALUES
end
GO

PRINT ('Migra tabella: Alert_Tipologia')
IF NOT EXISTS (select 1 from sys.tables tt 
    inner join sys.columns cc on tt.object_id = cc.object_id
    where tt.name = 'Alert_Tipologia'
    and cc.name = 'Utilizzo_GiasAPP')
    ALTER TABLE [dbo].[Alert_Tipologia] ADD [Utilizzo_GiasAPP] [smallint] NOT NULL DEFAULT(0) WITH VALUES
GO


