IF NOT EXISTS (select 1 from sys.tables tt 
    inner join sys.columns cc on tt.object_id = cc.object_id
    where tt.name = 'Alert_Entita'
    and cc.name = 'Id_Schema_Template')
    begin

        /* 31/05/2021 */
       /* Cancellati permessi doppi nella tabella CategTipologiaDocumentiXUtenti */
        IF EXISTS (select 1 from sys.tables tt where tt.name = 'CategTipologiaDocumentiXUtenti' ) and
            (select count(*) from [dbo].[CategTipologiaDocumentiXUtenti] where CategTipologiaDocumentiXUtenti.ID_Tipologia <> 0  and 
                exists (select * from [dbo].[CategTipologiaDocumentiXUtenti] permessi where permessi.PivaSuperUser = CategTipologiaDocumentiXUtenti.PivaSuperUser and 
                        permessi.Piva = CategTipologiaDocumentiXUtenti.Piva and 
                        permessi.Username = CategTipologiaDocumentiXUtenti.Username and
                        permessi.ID_Categoria = CategTipologiaDocumentiXUtenti.ID_Categoria and 
                        permessi.Autorizzato = CategTipologiaDocumentiXUtenti.Autorizzato and permessi.ID_Tipologia = 0)) > 0
        begin

            DELETE FROM CategTipologiaDocumentiXUtenti WHERE CategTipologiaDocumentiXUtenti.ID_Tipologia <> 0  and 
            exists (select * from CategTipologiaDocumentiXUtenti permessi where permessi.PivaSuperUser = CategTipologiaDocumentiXUtenti.PivaSuperUser and 
                        permessi.Piva = CategTipologiaDocumentiXUtenti.Piva and 
                        permessi.Username = CategTipologiaDocumentiXUtenti.Username and
                        permessi.ID_Categoria = CategTipologiaDocumentiXUtenti.ID_Categoria and 
                        permessi.Autorizzato = CategTipologiaDocumentiXUtenti.Autorizzato and permessi.ID_Tipologia = 0)

        end

        ALTER TABLE [dbo].[Alert_Entita] ADD [Id_Schema_Template] [int] NULL DEFAULT(0) WITH VALUES

    end
GO






