IF EXISTS (select 1 from reg_impianti_codici where id_cod= 1328)
BEGIN
    PRINT ('Sposto la data inizio portinnesto da reg_impianti_codici (id_cod 1328) a Reg_Impianti.Data_Inizio_Portinnesto')

    UPDATE reg_impianti    
        SET Data_Inizio_Portinnesto= convert(datetime,cod.val_cod,120)
    from   reg_impianti_codici  cod 
        inner join   reg_impianti
    ON cod.piva = reg_impianti.piva
        and   cod.sa_cod = reg_impianti.sa_cod
        and   cod.appezza = reg_impianti.APPEZZA
        and   cod.id_reg= reg_impianti.id_reg
        and   cod.id_cod= 1328
  
    delete from reg_impianti_codici where id_cod= 1328
END
GO


