END
GO

IF NOT EXISTS (select 1 from DW_CDG_Costi_Ricavi
where Fabbricato_Des != ''  ) BEGIN
     
    update DW_CDG_Costi_Ricavi set fabbricato_des = Fabbricati.Fabbricato_Des from 
        Fabbricati join
        CDG_Testata 
        on 
        CDG_Testata.piva = Fabbricati.piva and
        CDG_Testata.sa_cod = Fabbricati.sa_cod and
        CDG_Testata.Id_Destinazione = Fabbricati.Fabbricato_Cod
        join DW_CDG_Costi_Ricavi on
        DW_CDG_Costi_Ricavi.piva = CDG_Testata.piva and
        DW_CDG_Costi_Ricavi.id_agenda = CDG_Testata.id_agenda and
        DW_CDG_Costi_Ricavi.id_cdg = cdg_testata.id_cdg
        where (cdg_testata.pro_cod != 0 or cdg_testata.mat_cod !=0) 
    
END
GO


