    BEGIN
        PRINT('Sequenza_Tabelle.Nome_Tabella [' + @nomeTabella + '] : Aggiorno colonna [End] = ' + CAST(@limiteMaxEnd AS VARCHAR));
        UPDATE Sequenza_Tabelle SET [End] = @limiteMaxEnd WHERE Nome_Tabella = @nomeTabella;
    END

SET @nomeTabella = 'passaggiodistato_cod';
IF EXISTS (SELECT 1 FROM Sequenza_Tabelle WHERE Nome_Tabella = @nomeTabella AND [End] < @limiteMaxEnd)
    BEGIN
        PRINT('Sequenza_Tabelle.Nome_Tabella [' + @nomeTabella + '] : Aggiorno colonna [End] = ' + CAST(@limiteMaxEnd AS VARCHAR));
        UPDATE Sequenza_Tabelle SET [End] = @limiteMaxEnd WHERE Nome_Tabella = @nomeTabella;
    END

GO

DECLARE @nomeTabella AS VARCHAR(250) = 'Alert_Area';
DECLARE @nuova_base AS INT = 100;
DECLARE @nuovo_ultimo_valore AS INT = 100;

IF EXISTS (SELECT 1 FROM Sequenza_Tabelle WHERE Nome_Tabella = @nomeTabella AND Ultimo_Valore < @nuovo_ultimo_valore AND Base < @nuova_base)
    BEGIN
        PRINT('Sequenza_Tabelle.Nome_Tabella ['+ @nomeTabella +'] : Aggiorno colonna Ultimo_Valore con  + ' + CAST(@nuovo_ultimo_valore AS VARCHAR) + ' e la Base a '+ CAST(@nuova_base AS VARCHAR));
        UPDATE Sequenza_Tabelle SET Ultimo_Valore = Ultimo_Valore + @nuovo_ultimo_valore , Base = @nuova_base WHERE Nome_Tabella = @nomeTabella AND 
        Ultimo_Valore < @nuovo_ultimo_valore AND Base < @nuova_base;
    END

GO

