PRINT ('Tabella Stalla_Raggruppamenti: Aggiunto flag per raggruppamento base per importazione da BDN')
IF NOT EXISTS (SELECT 1 FROM sys.tables tt INNER JOIN sys.columns cc ON tt.object_id = cc.object_id 
WHERE tt.name = 'Stalla_Raggruppamenti' AND cc.name = 'Flag_BDN')
BEGIN
  ALTER TABLE Stalla_Raggruppamenti 
  ADD Flag_BDN [int] NULL DEFAULT 0 WITH VALUES

    -- Mi servo di questa query come "SEMAFORO" per assicurarmi che le seguenti query di sistemazione siano eseguite una sola volta --

-- Pulizia da DW costi di tutta la testata dove alcune righe sono state cancellate perché cambiata la specie ma ci sono ancora altre righe che avevano la specie giusta
    PRINT ('Pulizia da DW costi di tutta la testata dove alcune righe sono state cancellate perché cambiata la specie ma ci sono ancora altre righe che avevano la specie giusta')
    delete from dw_cdg_costi_ricavi where id_cdg in (
        select id_cdg from CDG_Dettagli where Id_CDG_Dettagli not in
        (select Id_CDG_Dettagli from dw_cdg_costi_ricavi) and
        Id_CDG  in
        (select Id_CDG from dw_cdg_costi_ricavi)
    )

 -- Valorizzazione qta2 (sup trattata) su raccolte autogenerate da conferimento 
   PRINT ('Valorizzazione qta2 (sup trattata) su raccolte autogenerate da conferimento')
    update m
    set m.qta2 = r.sup_imp
    from  mov_destinazioni m
    inner join agenda a on m.piva = a.piva and m.Id_Agenda = a.Id_Agenda
    inner join reg_impianti r on m.piva = r.piva and m.sa_cod = r.sa_cod and m.appezza = r.appezza and m.id_destinazione = r.id_reg
    where a.lav_cod = 125
    and m.Appezza <> 0
    and m.qta2 = 0

 -- Valorizzazione di quota distribuzione sulle semine da frazionamento e raccolte auto-generate
     --1. Lanciare questa query che sposta indietro la data dei dati errati per triggerare il bombardino
   PRINT ('Valorizzazione di quota distribuzione sulle semine da frazionamento e raccolte auto-generate')
    update Mov_Dettagli_Riferimenti set data_creazione = dateadd("d", -2,
        (select data_Movimento from movimenti where
        movimenti.piva = mov_dettagli_riferimenti.piva
        and movimenti.id_agenda = mov_dettagli_riferimenti.id_agenda
        and movimenti.cau_mov in ('2200', '2300'))
    )
    where id_agenda in (
        select AG.id_agenda from agenda AG, mov_destinazioni where lav_cod in (2,71,125) 
        and Mov_Dettagli_Riferimenti.piva = AG.piva
        and Mov_Dettagli_Riferimenti.id_agenda = AG.id_agenda
        and Mov_Dettagli_Riferimenti.lav_cod_rif = 4500

        and ag.piva = mov_destinazioni.piva
        and ag.id_agenda = mov_destinazioni.id_agenda
        and mov_destinazioni.Tipo_Destinazione = 0
        and mov_destinazioni.Appezza <> 0
        and mov_destinazioni.QuotaDistribuzione = 0
    )


    --2. Lanciare query per allineare il campo quotadistribuzione in base alla superfici degli impianti
    update mov_destinazioni set QuotaDistribuzione = (
    qta2
    /
    (select sum(qta2) from mov_destinazioni md 
        where md.piva = mov_destinazioni.piva and
           md.id_agenda = mov_destinazioni.id_agenda and
           md.id_mov = mov_destinazioni.id_mov and
           md.id_mov_det = mov_destinazioni.id_mov_det and
           md.Appezza <> 0 and
           md.Tipo_Destinazione = 0)
    )
    where id_agenda in (select id_agenda from agenda AG where lav_cod in (2,71,125) and mov_destinazioni.piva = ag.piva)
    and mov_destinazioni.Tipo_Destinazione = 0
    and mov_destinazioni.Appezza <> 0
    and mov_destinazioni.QuotaDistribuzione = 0
    and (select sum(qta2) from mov_destinazioni md 
        where md.piva = mov_destinazioni.piva and
           md.id_agenda = mov_destinazioni.id_agenda and
           md.id_mov = mov_destinazioni.id_mov and
           md.id_mov_det = mov_destinazioni.id_mov_det and
           md.Appezza <> 0 and
           md.Tipo_Destinazione = 0) <> 0

    -- Fix su op. colturali multicentro

   PRINT ('Fix su op. colturali multicentro')
    declare @data as date = '01/01/2022'
    declare @tolleranza_secondi as float = 2;
    declare @tolleranza_decimali as float = 0.01;

    -- DATI TRATTAMENTI
    declare @listLavCodTrattamenti table (lav_cod int);
    insert @listLavCodTrattamenti(lav_cod) values(74),(18),(158),(155),(13),(103); --LAVCOD_TRATTAMENTO_ANTIPARASSITARIO, LAVCOD_DISERBO, LAVCOD_DISSECCAMENTO, LAVCOD_GEODISINFESTAZIONE, LAVCOD_CONCIA_SEME, LAVCOD_TRATTAMENTO_FITOREGOLATORE
    declare @cauMovTrattamenti varchar(20) = '2050';  --CAU_TRATTAMENTO

    -- DATI FERTILIZZAZIONE
    declare @listLavCodFertilizzazioni table (lav_cod int);
    insert @listLavCodFertilizzazioni(lav_cod) values(14),(156),(124),(123),(26),(106); --LAVCOD_DISTRIBUZIONE_CONCIME, LAVCOD_SARCHIATURA_CONCIMAZIONE, LAVCOD_DISTRIBUZIONE_AMMENDANTI, LAVCOD_CONCIMAZIONE_FOGLIARE, LAVCOD_FERTIRRIGAZIONE, LAVCOD_TRATTAMENTO_ANTIBUTTERATURA
    declare @cauMovFertilizzazioni varchar(20) = '2300';  --CAU_LAVORAZIONE

    DECLARE @Cau_Mov INT
    DECLARE @Data_Creazione DATETIME
    DECLARE @Validita_Inizio DATETIME
    DECLARE @PIVA VARCHAR(100)
    DECLARE      @Id_Agenda INT
    DECLARE @Id_Mov INT
    DECLARE      @Id_Mov_Det INT
    DECLARE      @sup_totale FLOAT
    DECLARE      @qta FLOAT
    DECLARE      @qta_extra_totale_calcolata FLOAT
    DECLARE      @qta_extra_totale FLOAT

    DECLARE scorri CURSOR FOR

    WITH somma_superfici AS ( 
           SELECT sum(qta2) AS sup_totale, piva, id_agenda,id_mov, Id_Mov_Det
           FROM Mov_Destinazioni
           WHERE Appezza <> 0  
           GROUP BY  piva, id_agenda, id_mov, Id_Mov_Det
    )

    SELECT  
         M.Cau_Mov
        ,A.Data_Creazione
        ,A.Validita_Inizio
        ,A.PIVA
           ,A.Id_Agenda
        ,M.Id_Mov
           ,MD.Id_Mov_Det
           ,SS.sup_totale
           ,MD.Qta
        ,SS.sup_totale * MD.Qta as Qta_Extra_Totale_Calcolata
           ,MD.Qta_Extra_Totale
       
    FROM Agenda A
    JOIN Movimenti M
           ON A.piva = M.PIVA
           AND A.Id_Agenda = M.Id_Agenda 
    JOIN Movimenti_dettagli  MD
        ON A.piva = MD.PIVA
           AND A.Id_Agenda = MD.Id_Agenda 
           AND M.Id_Mov = MD.Id_Mov
    JOIN somma_superfici SS
           ON A.piva = SS.PIVA
           AND A.Id_Agenda = SS.Id_Agenda
           AND M.Id_Mov = SS.Id_Mov   
           AND MD.id_mov_det = SS.Id_Mov_Det

    WHERE A.Lav_Cod IN (select lav_cod from @listLavCodTrattamenti union select lav_cod from @listLavCodFertilizzazioni) 
    AND M.Cau_Mov IN (@cauMovTrattamenti, @cauMovFertilizzazioni)
    AND A.Data_Creazione >= @data
    AND ABS((SS.sup_totale * MD.Qta) - MD.Qta_Extra_Totale) > @tolleranza_decimali
    and EXISTS (
           select top(1) * from agenda as A1
           JOIN Movimenti M1
                 ON A1.piva = M1.PIVA
                 AND A1.Id_Agenda = M1.Id_Agenda 
           WHERE 
           A1.Id_Agenda <> A.Id_Agenda
        AND A1.Lav_Cod IN (select lav_cod from @listLavCodTrattamenti union select lav_cod from @listLavCodFertilizzazioni) 
           AND M1.Cau_Mov IN (@cauMovTrattamenti, @cauMovFertilizzazioni)
           AND ABS(DATEDIFF(SECOND, A1.Data_Creazione, A.Data_Creazione)) <= @tolleranza_secondi
    )
    ORDER BY M.cau_mov, A.Data_Creazione, A.Id_Agenda

    BEGIN TRANSACTION

    OPEN scorri
           FETCH NEXT FROM scorri INTO @Cau_Mov, @Data_Creazione, @Validita_Inizio, @PIVA, @Id_Agenda, @Id_Mov, @Id_Mov_Det, @sup_totale, @qta, @qta_extra_totale_calcolata, @qta_extra_totale
                 WHILE @@FETCH_STATUS = 0
                        BEGIN  
                                              
                              UPDATE MD SET MD.Qta_Extra_Totale = @qta_extra_totale_calcolata
                              FROM 
                                  Movimenti_dettagli MD
                                     WHERE MD.PIVA = @PIVA
                                     AND MD.Id_Agenda = @Id_Agenda
                                     AND MD.Id_Mov = @Id_Mov
                                     AND MD.id_mov_det = @Id_Mov_Det
                                 
                              FETCH NEXT FROM scorri INTO @Cau_Mov, @Data_Creazione, @Validita_Inizio, @PIVA, @Id_Agenda, @Id_Mov, @Id_Mov_Det, @sup_totale, @qta, @qta_extra_totale_calcolata, @qta_extra_totale
                        END

    CLOSE scorri
    DEALLOCATE scorri

    COMMIT
END
GO

 
 
