  ALTER TABLE [dbo].[Parco_MacchinexCaratteristiche]  DROP  PK_Parco_MacchinexCaratteristiche

  ALTER TABLE [dbo].[Parco_MacchinexCaratteristiche] add CONSTRAINT [PK_Parco_MacchinexCaratteristiche] PRIMARY KEY CLUSTERED 
    (
