--Vanni, 15/05/2023: impostati i valori nella tabella GIS_LayerElementiGrafici per il super user, sovrascrivendo il super-user provvisorio '123'
UPDATE gl 
SET    PivaSuperUser = @PivaSuperUser, Utente = @SuperUserUsername
from   GIS_LayerElementiGrafici gl 
WHERE  PivaSuperUser = '123' 
and    not exists  
( 
  Select 1 
  from   GIS_LayerElementiGrafici ii 
  where  gl.LayerElementiGrafici_cod=ii.LayerElementiGrafici_cod 
  and    ii.PivaSuperUser = @PivaSuperUser 
  and    ii.Utente = @SuperUserUsername
)  
--Fine vanni, 15/05/2023

if not exists (select 1 from GIS_LayerElementiGrafici where utente = @SuperUserUsername and LayerElementiGrafici_Cod > 0)
begin
    set @SuperUserUsername = 'a'
end

--Vanni, 05/10/2023, nuova logica di inserimento, vengono comunque inseriti record mancanti.
--if not exists (select 1 from GIS_LayerElementiGrafici_Anagrafica where LayerElementiGrafici_Cod = 1 )
--begin
    insert GIS_LayerElementiGrafici_Anagrafica (
        [PivaSuperUser],
        [LayerElementiGrafici_Cod],
        [TipologiaLayer_cod],
        [LayerElementiGrafici_Des],
        [Flag_Inserimento], 
        [Flag_Modifica],
        [Flag_Cancellazione],
        [Flag_Informazioni],
        [Flag_SingolaDataSignificativa]
    )
    
    select distinct
          @PivaSuperUser as PivaSuperUser
        , LayerElementiGrafici_Cod
        , TipologiaLayer_cod
        , LayerElementiGrafici_Des
        , case when LayerElementiGrafici_Cod in (-2, -1, 3, 66, 63, 60, 55, 54, 51, 50, 34, 33, 17, 11, 87, 89) then 0 else 1 end as flag_inserimento
        , case when LayerElementiGrafici_Cod in (-2, -1, 3, 66, 63, 60, 55, 54, 50, 34, 33, 17, 11, 87, 89) then 0 else 1 end as flag_modifica
        , case when LayerElementiGrafici_Cod in (-2, -1, 3, 66, 63, 60, 55, 54, 51, 50, 34, 33, 17, 11, 87, 89) then 0 else 1 end as flag_cancellazione
        , case when LayerElementiGrafici_Cod in (-2, -1, 1, 2, 3, 11, 13, 17, 18, 19, 33, 34, 50, 51, 54, 55, 60, 63, 89) then 0 else 1 end as flag_informazioni
        , case when LayerElementiGrafici_Cod in (13, 50, 51, 54, 60, 63, 66, 87, 88) then 1 else 0 end as Flag_SingolaDataSignificativa
    from GIS_LayerElementiGrafici g
    where TipologiaLayer_cod = 1 and LayerElementiGrafici_Cod > 0
    and utente = @SuperUserUsername
    and not exists (
        select 1
        from GIS_LayerElementiGrafici_Anagrafica i
        where i.LayerElementiGrafici_cod = g.LayerElementiGrafici_Cod
    )
--end


