insert GIS_LayerElementiGraficiXTipoOggetto(pivaSuperUser, LayerElementiGrafici_Cod,  GIS_TipoOggetto_COd)
select 
    @PivaSuperUser as PivaSuperUser
    , LayerElementiGrafici_Cod
    , case when LayerElementiGrafici_Cod in (13, 67, 86) then 2 else 1 end as GIS_TipoOggetto
from GIS_LayerElementiGrafici_anagrafica aa
where aa.LayerElementiGrafici_Cod < 1000000
and aa.LayerElementiGrafici_Cod > 0   --Layer negativi non richiedono un tipoOggetto
and aa.LayerElementiGrafici_Cod <> 87 --Tecnici in campo non richiede un tipoOggetto
and not exists (
    select 1
    from GIS_LayerElementiGraficiXTipoOggetto g
    where g.LayerElementiGrafici_Cod = aa.LayerElementiGrafici_Cod
)
