IF EXISTS (SELECT 1 from GIS_TipoOggetto WHERE FeatureTypeId IS NULL)
BEGIN
    PRINT('GIS_TipoOggetto: popola colonna FeatureTypeId')
    UPDATE GIS_TipoOggetto 
    SET FeatureTypeId =
    CASE
        WHEN GIS_TipoOggetto_GMLElemetName = 'POINT' THEN 1
        WHEN GIS_TipoOggetto_GMLElemetName = 'MULTIPOINT' THEN 2
        WHEN GIS_TipoOggetto_GMLElemetName = 'LINESTRING' THEN 3
        WHEN GIS_TipoOggetto_GMLElemetName = 'MULTILINESTRING' THEN 4
        WHEN GIS_TipoOggetto_GMLElemetName = 'POLYGON' THEN 5
        WHEN GIS_TipoOggetto_GMLElemetName = 'MULTIPOLYGON' THEN 6
    END
    WHERE FeatureTypeId IS NULL
END
