-- standard (1)
if not exists (
SELECT 1
    FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS t
        inner join INFORMATION_SCHEMA.CONSTRAINT_COLUMN_USAGE u
            on t.CONSTRAINT_NAME = u.CONSTRAINT_NAME
    WHERE t.CONSTRAINT_NAME='PK_GIS_LayerTessere' 
    and u.column_NAME in ( 'TipologiaLayer_cod')
)
update t
set TipologiaLayer_cod = 1
from GIS_LayerTiles t
where LayerTiles_Des in (

     'AppldRate'
    ,'Speed'
    ,'GPS_Status'
    ,'Height'
    ,'Swath'
    ,'Status_Txt'
    , 'CAP_N+'

)
and TipologiaLayer_cod = 0
