-- GIS_LayerTiles: update LayerTiles_Des avversità con specie vegetale

IF EXISTS (SELECT 1 FROM GIS_LayerTiles 
           WHERE TipologiaLayer_cod = 7 
           AND   LayerTiles_Des not like '%\[%\]%' ESCAPE '\') 
    PRINT ('GIS_LayerTiles: update LayerTiles_Des avversità con specie vegetale')
    update GIS_LayerTiles
    set LayerTiles_Des = 
    (
    select udm.UDM_DES collate Latin1_General_CI_AS  + ' [' + veg.veg_des + ']' as BetterDescription
    from   GIS_LayerTiles t
           inner join MisuraxAvversita mxa on t.LayerTiles_Cod = mxa.COD
           inner join Avversita av on av.Av_Cod = mxa.AV_COD
           inner join SpecieVegetali veg on veg.Veg_Cod = mxa.VEG_COD
           inner join UnitaMisura udm on udm.UDM_COD = mxa.UDM_COD
    where  t.PivaSuperUser = GIS_LayerTiles.PivaSuperUser
    and    t.LayerElementiGrafici_Cod = GIS_LayerTiles.LayerElementiGrafici_Cod
    and    t.Utente = GIS_LayerTiles.Utente
    and    t.LayerTiles_Cod = GIS_LayerTiles.LayerTiles_Cod
    and    t.TipologiaLayer_cod = GIS_LayerTiles.TipologiaLayer_cod
    )
    where TipologiaLayer_cod = 7
    and LayerTiles_Des not like '%\[%\]%' ESCAPE '\'
GO


