-- Inserimento tabella GIS_LayerElementiGraficiXUtente

declare @SuperUserUsername varchar(1000)
set @SuperUserUsername = (SELECT  top 1 [Utente_Profilo] FROM $(UtentiDB).dbo.Utenti_Profili Where [Utente] = [Utente_Profilo]) 

declare @PivaSuperUser as varchar(25)
set @PivaSuperUser = (SELECT  top 1 [USER] FROM utentiximprese)

PRINT ('Inserimento tabella [GIS_LayerElementiGraficiXUtente]')

insert GIS_LayerElementiGraficiXUtente (
        layerElementiGrafici_cod
      , utente
      , Flag_Inserimento 
      , Flag_Modifica 
      , Flag_Cancellazione 
      , Flag_Informazioni   
      , Flag_Amministrazione  
      , inviato
      , dataInvio
      , data_Creazione
      , data_Modifica
      , username_Creazione
      , username_Modifica
)
select 
      anag.layerElementiGrafici_cod
      , case when  d.username is null then @SuperUserUsername else d.username end as utente
      , 1 as Flag_Inserimento 
      , 1 as Flag_Modifica 
      , 1 as Flag_Cancellazione 
      , 1 as Flag_Informazioni   
      , 1 as Flag_Amministrazione  
      , 0 as inviato
      , null as dataInvio
      , cast(getdate() as date ) as data_Creazione
      , cast(getdate() as date ) as data_Modifica
      , case when  d.username is null then @SuperUserUsername else d.username end as username_Creazione
      , case when  d.username is null then @SuperUserUsername else d.username end as username_Modifica
     
from gis_layerElementiGrafici_anagrafica anag
    left join $(utentiDB).dbo.utenti_Dettagli d
        on ( d.codFisc = anag.username_Creazione or d.username = anag.username_Creazione)
where LayerElementiGrafici_Cod >= 1000000
and TipologiaLayer_cod = 1
and not exists (
    select 1
    from GIS_LayerElementiGraficiXUtente uu
    where uu.utente = case when  d.username is null then @SuperUserUsername else d.username end
    and uu.layerElementiGrafici_cod = anag.LayerElementiGrafici_Cod
)

