---- Tabella Mov_Dettaglio_Tecnico_Extra: aumento dimensione campo Precisazioni
IF EXISTS (select 1 from sys.tables tt 
inner join sys.columns cc on tt.object_id = cc.object_id 
where tt.name = 'Mov_Dettaglio_Tecnico_Extra' 
  and cc.name = 'Precisazioni'
  and cc.max_length < 4000)
BEGIN
    declare @Command  nvarchar(1000)
    declare @dfName nvarchar(1000)
    select @dfName = d.name
     from sys.tables t
      join sys.default_constraints d on d.parent_object_id = t.object_id
      join sys.columns c on c.object_id = t.object_id and c.column_id = d.parent_column_id
     where t.name = 'Mov_Dettaglio_Tecnico_Extra'
      and t.schema_id = schema_id('dbo')
      and c.name = 'Precisazioni'

    SET @Command = 'ALTER TABLE dbo.[Mov_Dettaglio_Tecnico_Extra] DROP CONSTRAINT  ' + @dfName + ' '
    EXEC (@Command)

    alter table [dbo].[Mov_Dettaglio_Tecnico_Extra] alter column [Precisazioni] nvarchar(4000) not null

    ALTER TABLE [dbo].[Mov_Dettaglio_Tecnico_Extra] ADD  DEFAULT ('') FOR [Precisazioni]
END
GO


