-- CAMBIO TIPOLOGIA COLONNA ATTIVITA' 6112 INIZIO --

IF NOT EXISTS (select 1 from sys.tables tt inner join sys.columns cc on tt.object_id = cc.object_id inner join sys.types ty on ty.user_type_id = cc.user_type_id
where tt.name = 'GIS_LayerElementiGrafici' and cc.name = 'LayerElementiGrafici_Cod' and LOWER(ty.name) = 'int')
BEGIN

    UPDATE $(ServerDB).[dbo].[GIS_LayerElementiGrafici] Set LayerElementiGrafici_Cod = XYZ.Gruppi_Utente_cod
    FROM(
    SELECT LEG.[PivaSuperUser] piva
          , LEG.[LayerElementiGrafici_Cod] legc
          , LEG.[Utente] ut
          , LEG.[TipologiaLayer_cod] tipo
          , GU.Gruppi_Utente_Identificativo
          , GU.Gruppi_Utente_cod
      FROM $(ServerDB).[dbo].[GIS_LayerElementiGrafici] LEG 
      inner join $(UtentiDB).[dbo].[Gruppi_Utente] GU on GU.Gruppi_Utente_Identificativo = LEG.LayerElementiGrafici_Cod) XYZ
      WHERE PivaSuperUser = XYZ.piva 
      AND LayerElementiGrafici_Cod = XYZ.legc 
      AND Utente = XYZ.ut 
      AND TipologiaLayer_cod = XYZ.tipo;

      ALTER TABLE $(ServerDB).[dbo].[GIS_LayerElementiGrafici] DROP CONSTRAINT [PK_GIS_LayerElementiGrafici];

      ALTER TABLE $(ServerDB).[dbo].[GIS_LayerElementiGrafici] ALTER COLUMN LayerElementiGrafici_Cod int NOT NULL;

      ALTER TABLE $(ServerDB).[dbo].[GIS_LayerElementiGrafici] ADD CONSTRAINT [PK_GIS_LayerElementiGrafici] PRIMARY KEY CLUSTERED 
    (
        [PivaSuperUser] ASC,
        [LayerElementiGrafici_Cod] ASC,
        [Utente] ASC,
        [TipologiaLayer_cod] ASC
    )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, IGNORE_DUP_KEY = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
END
GO
