declare @PivaSuperUser as nvarchar(25)
set @PivaSuperUser = (SELECT  top 1 [USER] FROM utentiximprese)


declare @SuperUserUsername varchar(1000)
set @SuperUserUsername = (SELECT  top 1 [Utente_Profilo] FROM $(UtentiDB).dbo.Utenti_Profili Where [Utente] = [Utente_Profilo]) 

declare @MaxLayerTiles_cod int

PRINT ('Tematismo per mappe di prescrizione: CAP_N+ su utente super-user')

IF  @SuperUserUsername is not null AND NOT EXISTS (
    SELECT 1
    FROM [dbo].[GIS_LayerTiles] 
    WHERE [PivaSuperUser] = @PivaSuperUser 
    AND [LayerElementiGrafici_Cod] = 51 
    AND [TipologiaLayer_cod] = 1
    AND [LayerTiles_Des] = 'CAP_N+'
) 
BEGIN

    
    select @MaxLayerTiles_cod = max(LayerTiles_Cod)
    from [dbo].[GIS_LayerTiles] 
    WHERE [PivaSuperUser] = @PivaSuperUser 
    AND [LayerElementiGrafici_Cod] = 51 
    AND [Utente] = @SuperUserUsername 
    AND [TipologiaLayer_cod] = 1

    if @MaxLayerTiles_cod is null
        set @MaxLayerTiles_cod = 1

     INSERT INTO [dbo].[GIS_LayerTiles] ([PivaSuperUser], [LayerElementiGrafici_Cod], [Utente], [LayerTiles_Cod], [LayerTiles_Des], [Colore_Primario], [Colore_Secondario], [Colore_Base], [varianza], [inviato], [datainvio], [Data_Creazione], [Data_Modifica], [Username_Creazione], [Username_Modifica], [Validita_Inizio], [Validita_Fine], [TipologiaLayer_cod])
     VALUES (@PivaSuperUser, 51, @SuperUserUsername, @MaxLayerTiles_cod, 'CAP_N+', 'ff0000', '7FCF78', '000000', 6, 0, NULL, '20220823', '20230412', @SuperUserUsername, @SuperUserUsername, '19000101', '21001231', 1)

END



print ('Tematismo per indici produttività')

IF  @SuperUserUsername is not null AND NOT EXISTS (
    SELECT 1
    FROM [dbo].[GIS_LayerTiles] 
    WHERE [PivaSuperUser] = @PivaSuperUser 
    AND [LayerElementiGrafici_Cod] = 91 
    AND [TipologiaLayer_cod] = 1
    and [LayerTiles_Cod] = -21    
) 
