[LayerTiles_Des] = 'Produttività (q/ha)' 
WHERE [PivaSuperUser] = @PivaSuperUser AND [LayerElementiGrafici_Cod] = 91 AND [LayerTiles_Cod] = -20 AND [TipologiaLayer_cod] = 1

