-- Aggiunta identity alle tabelle dei codici
IF NOT EXISTS (SELECT 1 FROM sys.tables tt 
               INNER JOIN sys.columns cc ON tt.object_id = cc.object_id 
               WHERE tt.NAME = 'Imprese_Codici' AND cc.NAME = 'ID')
BEGIN
    ALTER TABLE Imprese_Codici
        ADD		[ID] [int] NOT NULL IDENTITY(1,1)

    DECLARE @PK_CONSTRAINT VARCHAR(50)
    SET @PK_CONSTRAINT = (SELECT ISNULL(CONSTRAINT_NAME,'')
                          FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS t
                          WHERE TABLE_NAME = 'Imprese_Codici' 
                          AND CONSTRAINT_TYPE = 'PRIMARY KEY')

     IF (@PK_CONSTRAINT <> '')
     BEGIN
        EXEC('ALTER TABLE Imprese_Codici DROP CONSTRAINT ' + @PK_CONSTRAINT)
     END

     ALTER TABLE Imprese_Codici ADD 
        CONSTRAINT [PK_Imprese_Codici] PRIMARY KEY  
        (
            [ID]
        )  ON [PRIMARY] 
END
GO

