-- Migra tabella: UMA_Causali
IF NOT EXISTS (select 1 from sys.tables tt where tt.name = 'UMA_Causali' )

    BEGIN

    PRINT ('Migra tabella: UMA_Causali')

    CREATE TABLE [dbo].[UMA_Causali](
        [Piva_SuperUser] [nvarchar](25) NOT NULL,
        [Causale_Tipo] [int] NOT NULL,
        [Causale_Cod] [int] NOT NULL,
        [Causale_Des] [varchar](100) NOT NULL,
        [inviato] [smallint] NULL default 0,
        [datainvio] [datetime] NULL,
        [Data_Creazione] [datetime] NULL DEFAULT (getdate()),
        [Data_Modifica] [datetime] NULL DEFAULT (getdate()),
        [Username_Creazione] [varchar](250) NULL DEFAULT ('agronica'),
        [Username_Modifica] [varchar](250) NULL DEFAULT ('agronica'),
        [Validita_Inizio] [datetime] NULL DEFAULT ('01/01/1900'),
        [Validita_Fine] [datetime] NULL DEFAULT ('31/12/2100'),
     CONSTRAINT [PK_UMA_Causali] PRIMARY KEY CLUSTERED 
    (
        [Piva_SuperUser] ASC,
        [Causale_Tipo] ASC,
        [Causale_Cod] ASC
    )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
    ) ON [PRIMARY]

    PRINT ('UMA_Causali: inserimento causali')

    DECLARE @PivaSuperUser AS VARCHAR(25)

    SET @PivaSuperUser = (SELECT TOP 1 [USER] FROM utentiximprese)

    -- Causali di non utilizzo (Causale_Tipo=1)
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,1,1,'Variazione di intestazione');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,1,2,'Variazione delle superficie in diminuzione');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,1,3,'Decesso del titolare');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,1,4,'Cessazione dell’impresa');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,1,5,'Avversità atmosferiche');

    -- Causali recupero accise (Causale_Tipo=2)
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,2,1,'Litri in esubero');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,2,2,'Rimanenze non riassegnate');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,2,3,'Rimanenze non riassegnate + Litri in esubero');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,2,4,'Rendicontazione mancante');
    INSERT INTO UMA_Causali (Piva_SuperUser,Causale_Tipo,Causale_Cod,Causale_Des) VALUES (@PivaSuperUser,2,5,'Rimanenze senza pratiche');

    END

    GO

