-- Aggiunta la colonna Validita_Inizio alla chiave primaria di UMA_UF_Colture

IF (
    SELECT  COUNT(*)
    FROM    INFORMATION_SCHEMA.TABLE_CONSTRAINTS AS C
            JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE AS K ON C.TABLE_NAME = K.TABLE_NAME
                                                                AND C.CONSTRAINT_CATALOG = K.CONSTRAINT_CATALOG
                                                                AND C.CONSTRAINT_SCHEMA = K.CONSTRAINT_SCHEMA
                                                                AND C.CONSTRAINT_NAME = K.CONSTRAINT_NAME
    WHERE   C.CONSTRAINT_TYPE = 'PRIMARY KEY'
            AND C.TABLE_NAME = 'UMA_UF_Colture'
            AND K.COLUMN_NAME = 'Validita_Inizio') < 1

        BEGIN

        Update UMA_UF_Colture SET Validita_Inizio = Cast('01/01/1900' as datetime) where Validita_Inizio IS NULL

        ALTER TABLE UMA_UF_Colture ALTER COLUMN Validita_Inizio dateTime NOT NULL

        ALTER TABLE UMA_UF_Colture DROP CONSTRAINT PK_UMA_UF_Colture;
 
        ALTER TABLE UMA_UF_Colture ADD CONSTRAINT PK_UMA_UF_Colture 
            PRIMARY KEY (Occupazione_Cod, Destinazione_Cod, Uso_Cod, Qualita_Cod, Validita_Inizio);

        END

GO

