IF EXISTS (select 1 from sys.tables tt
    inner join sys.columns cc on tt.object_id = cc.object_id
    where tt.name = 'UMA_Gruppi_Allevamento') 
    
    IF NOT EXISTS (select 1 from UMA_Gruppi_Allevamento)
        BEGIN 
            Insert into UMA_Gruppi_Allevamento ([Regione_Cod]
          ,[UMA_AllGru_Cod]
          ,[UMA_AllGru_Des]
          ,[inviato]
          ,[datainvio]
          ,[Data_Creazione]
          ,[Data_Modifica]
          ,[Username_Creazione]
          ,[Username_Modifica]
          ,[Validita_Inizio]
          ,[Validita_Fine]) 
          select Distinct [Regione_Cod]
          ,[UMA_AllGru_Cod]
          ,[UMA_AllGru_Des]
          ,MIN([inviato]) as Inviato
          ,MIN([datainvio]) as datainvio
          ,MIN([Data_Creazione]) as Data_Creazione
          ,MIN([Data_Modifica]) as Data_Modifica
          ,MIN([Username_Creazione]) as Username_Creazione
          ,MIN([Username_Modifica]) as Username_Modifica
          ,MIN([Validita_Inizio]) as Validita_Inizio
          ,MIN([Validita_Fine]) as Validita_Fine from UMA_Allevamenti
          GROUP BY Regione_Cod, UMA_AllGru_Cod, UMA_AllGru_Des
        END
GO

