-- Tabella MisuraXIndiciMaturita_Anagrafiche: Nuova colonna Anag_Cod
IF NOT EXISTS (SELECT 1 FROM sys.tables tt INNER JOIN sys.columns cc ON tt.object_id = cc.object_id
               WHERE tt.name = 'MisuraXIndiciMaturita_Anagrafiche' and cc.name = 'Anag_Cod')
BEGIN

    PRINT ('Tabella MisuraXIndiciMaturita_Anagrafiche: Nuova colonna Anag_Cod')
    ALTER TABLE MisuraXIndiciMaturita_Anagrafiche ADD Anag_Cod INT NOT NULL DEFAULT 0;

    PRINT ('Tabella MisuraXIndiciMaturita_Anagrafiche: Inserimento valori colonna Anag_Cod')
    EXEC sp_executesql N'
    WITH NumberedRows AS (
        SELECT 
            Ind_Mat_Cod, Udm_Cod, Anag_valore, 
            ROW_NUMBER() OVER (ORDER BY Ind_Mat_Cod, Udm_Cod, Anag_valore) AS RowNum
        FROM MisuraXIndiciMaturita_Anagrafiche
    )
    UPDATE 
        MisuraXIndiciMaturita_Anagrafiche
    SET 
        Anag_Cod = NumberedRows.RowNum
    FROM 
        MisuraXIndiciMaturita_Anagrafiche
    JOIN 
        NumberedRows 
        ON MisuraXIndiciMaturita_Anagrafiche.Ind_Mat_Cod = NumberedRows.Ind_Mat_Cod
        AND MisuraXIndiciMaturita_Anagrafiche.Udm_Cod = NumberedRows.Udm_Cod
        AND MisuraXIndiciMaturita_Anagrafiche.Anag_valore = NumberedRows.Anag_valore;';

    PRINT ('Tabella MisuraXIndiciMaturita_Anagrafiche: Inserimento valore massimo di Anag_Cod in Sequenza_Tabelle')
    EXEC sp_executesql N'
        declare @maxAnagCod as int
        set @maxAnagCod = ISNULL((SELECT MAX(Anag_Cod) FROM MisuraXIndiciMaturita_Anagrafiche),0)

        IF @maxAnagCod > 0
        BEGIN
            IF EXISTS (SELECT 1 FROM Sequenza_Tabelle WHERE Nome_Tabella = ''misuraxindicimaturita_anagrafiche'')
            BEGIN

                UPDATE Sequenza_Tabelle
                SET Ultimo_Valore = @maxAnagCod
                WHERE Nome_Tabella = ''misuraxindicimaturita_anagrafiche''
            END
            ELSE
            BEGIN
                INSERT INTO Sequenza_Tabelle 
                (Nome_Tabella, Ultimo_Valore, Base, [End], inviato, datainvio, Data_Creazione, 
                    Data_Modifica, Username_Creazione, Username_Modifica)
                VALUES
                (''misuraxindicimaturita_anagrafiche'',@maxAnagCod,0,2000000000,0,null,GETDATE(),GETDATE(),''script'',''script'')
            END
        END'
END
GO

