        inner join INFORMATION_SCHEMA.CONSTRAINT_COLUMN_USAGE u
            on t.CONSTRAINT_NAME = u.CONSTRAINT_NAME
    WHERE t.CONSTRAINT_NAME='PK_Lista_Regioni' and u.column_NAME = 'Stato_Country'
)
BEGIN
    declare @PrimaryKeyName sysname = 
        (select CONSTRAINT_NAME 
         from INFORMATION_SCHEMA.TABLE_CONSTRAINTS 
         where CONSTRAINT_TYPE = 'PRIMARY KEY' and TABLE_SCHEMA='dbo' and TABLE_NAME = 'Lista_Regioni'
        )

    IF @PrimaryKeyName is not null
    begin
        declare @SQL_PK NVARCHAR(MAX) = 'alter table dbo.Lista_Regioni drop constraint ' + @PrimaryKeyName
        PRINT (@SQL_PK)
        EXEC sp_executesql @SQL_PK;
    end

    ALTER TABLE [dbo].[Lista_Regioni] ADD  CONSTRAINT [PK_Lista_Regioni] PRIMARY KEY CLUSTERED 
    (
        [Stato_Country] ASC,
        [REG] ASC
    ) ON [PRIMARY]
END
GO

