IF (
    SELECT is_identity FROM sys.columns WHERE object_name(object_id) = 'Guida_Impostazioni_Sezioni' AND name = 'Sezione_Cod'
) = 1
BEGIN
    PRINT CHAR(10) + 'Colonna Sezione_Cod in tabella Guida_Impostazioni_Sezioni HA IDENTITY'

    SET XACT_ABORT, ANSI_PADDING, ANSI_WARNINGS, CONCAT_NULL_YIELDS_NULL, ARITHABORT, QUOTED_IDENTIFIER, ANSI_NULLS ON

    BEGIN TRANSACTION

        PRINT '-- Creo tabella fittizia (uguale all''originale, ma senza identity)'
        CREATE TABLE [dbo].[Guida_Impostazioni_Sezioni_NOID](
            [Sezione_Cod] [int] NOT NULL,
            [Label] [nvarchar](250) NULL,
            [Espandibile] [int] NULL,
            [Flag_Livello] [int] NOT NULL DEFAULT (0),
            [Note] [nvarchar](4000) NULL,
            [inviato] [smallint] NULL DEFAULT (0),
            [datainvio] [datetime] NULL,
            [Data_Creazione] [datetime] NULL DEFAULT (getdate()),
            [Data_Modifica] [datetime] NULL DEFAULT (getdate()),
            [Username_Creazione] [varchar](250) NULL DEFAULT ('agronica'),
            [Username_Modifica] [varchar](250) NULL DEFAULT ('agronica'),
            [Validita_Inizio] [datetime] NULL DEFAULT ('01/01/1900'),
            [Validita_Fine] [datetime] NULL DEFAULT ('31/12/2100'),
         CONSTRAINT [PK_Guida_Impostazioni_Sezioni_NOID] PRIMARY KEY CLUSTERED 
        (
            [Sezione_Cod] ASC
        )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
        ) ON [PRIMARY]

        PRINT '-- Switcho i dati delle due tabelle'
        ALTER TABLE [Guida_Impostazioni_Sezioni] SWITCH TO [Guida_Impostazioni_Sezioni_NOID]

        PRINT '-- Drop della tabella originale'
        IF NOT EXISTS (SELECT 1 FROM Guida_Impostazioni_Sezioni)
            DROP TABLE Guida_Impostazioni_Sezioni

        PRINT '-- Rinomino la tabella fittizia con il nome della originale'
        EXEC sys.sp_rename 'Guida_Impostazioni_Sezioni_NOID', 'Guida_Impostazioni_Sezioni', 'OBJECT'

        PRINT CHAR(10) + '** Attributo IDENTITY rimosso da colonna Sezione_Cod in tabella Guida_Impostazioni_Sezioni **'+ CHAR(10)

    COMMIT TRANSACTION

END
ELSE
    PRINT CHAR(10) + 'Colonna Sezione_Cod in tabella Guida_Impostazioni_Sezioni NON HA IDENTITY'
GO



