/* ---------------------- Agronica_Log_Agenda  --------------------- */
/* ----------------------------------------------------------------- */

 

IF EXISTS (select 1 from sys.views where name = 'Agronica_Log_Agenda_UltimaOperazione')
    DROP VIEW Agronica_Log_Agenda_UltimaOperazione
GO
CREATE VIEW Agronica_Log_Agenda_UltimaOperazione AS
    WITH CTE AS (
        SELECT 
                SuperUser, Utente
              , Data_Ora_Lavorazione, Des_Lib
              , Id_Agenda, Piva, Sa_Cod, Lav_Cod
              , Data_Ora_RegistrazioneLog, Id_Servizio, Origine, Raccoglitore_Cod, Tipo_Operazione 
              , ROW_NUMBER() OVER (PARTITION BY Piva, Id_Agenda ORDER BY Data_Ora_RegistrazioneLog DESC, ID DESC) AS NumeroRiga
        FROM Agronica_Log_Agenda
    )

    SELECT UltimaAzione.SuperUser AS SuperUser, UltimaAzione.Utente,
            UltimaAzione.Data_Ora_Lavorazione, UltimaAzione.Des_Lib,
            ISNULL(UltimaAzione.Id_Agenda, 0) AS Id_Agenda, ISNULL(UltimaAzione.Piva, '') AS Piva, 
            UltimaAzione.Sa_Cod, UltimaAzione.Lav_Cod,
            UltimaAzione.Data_Ora_RegistrazioneLog, UltimaAzione.Id_Servizio,
    (CASE 
        WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_operazione IS NULL THEN 1 --'INSERT'
        WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_operazione = 3 THEN 2 --'MODIFICA'
        WHEN UltimaAzione.Tipo_Operazione = 2 THEN 2 --'MODIFICA DIRETTA'
        WHEN UltimaAzione.Tipo_Operazione = 3 THEN 3 --'DELETE'
        ELSE UltimaAzione.Tipo_Operazione
    END
    ) As UltimaOperazione, UltimaAzione.Origine, ISNULL(UltimaAzione.Raccoglitore_Cod, 0) AS Raccoglitore_Cod
    FROM CTE UltimaAzione
    LEFT JOIN CTE PenultimaAzione ON PenultimaAzione.Piva = UltimaAzione.Piva AND PenultimaAzione.Id_Agenda = UltimaAzione.Id_Agenda AND PenultimaAzione.NumeroRiga = 2
    WHERE UltimaAzione.NumeroRiga = 1

GO



IF EXISTS (select 1 from sys.views where name = 'Agronica_Log_Anagrafe_UltimaOperazione')
    DROP VIEW [dbo].[Agronica_Log_Anagrafe_UltimaOperazione]
GO
CREATE VIEW [dbo].[Agronica_Log_Anagrafe_UltimaOperazione] AS
    WITH CTE AS (
            SELECT 
                     SuperUser, Utente, Tipo, Chiave, Id_Budget
                   , Param1, Param2, Param3, Param4, Param5, Param6
                   , Data_Ora_RegistrazioneLog, Note, Id_Servizio, Origine, Tipo_Operazione 
                   , ROW_NUMBER() OVER (PARTITION BY Tipo, Chiave, Id_Budget ORDER BY Data_Ora_RegistrazioneLog DESC, ID DESC) AS NumeroRiga
            FROM [dbo].[Agronica_Log_Anagrafe]
        )

        SELECT UltimaAzione.SuperUser AS SuperUser, UltimaAzione.Utente
                , ISNULL(UltimaAzione.Tipo, '') AS Tipo, ISNULL(UltimaAzione.Chiave, '') AS Chiave, UltimaAzione.Id_Budget
                , COALESCE(UltimaAzione.Param1, PenultimaAzione.Param1) AS Param1
                , COALESCE(UltimaAzione.Param2, PenultimaAzione.Param2) AS Param2
                , COALESCE(UltimaAzione.Param3, PenultimaAzione.Param3) AS Param3
                , COALESCE(UltimaAzione.Param4, PenultimaAzione.Param4) AS Param4
                , COALESCE(UltimaAzione.Param5, PenultimaAzione.Param5) AS Param5
                , COALESCE(UltimaAzione.Param6, PenultimaAzione.Param6) AS Param6
                , UltimaAzione.Data_Ora_RegistrazioneLog, UltimaAzione.Note, UltimaAzione.Id_Servizio, 
        (CASE 
            WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_Operazione IS NULL THEN 1 --'INSERT'
            WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_Operazione = 3 THEN 2 --'MODIFICA'
            WHEN UltimaAzione.Tipo_Operazione = 2 THEN 2 --'MODIFICA DIRETTA'
            WHEN UltimaAzione.Tipo_Operazione = 3 THEN 3 --'DELETE'
            ELSE UltimaAzione.Tipo_Operazione
        END
        ) AS UltimaOperazione, UltimaAzione.Origine
        FROM CTE UltimaAzione
        LEFT JOIN CTE PenultimaAzione 
            ON PenultimaAzione.Tipo = UltimaAzione.Tipo 
            AND PenultimaAzione.Chiave = UltimaAzione.Chiave 
            AND PenultimaAzione.NumeroRiga = 2
        WHERE UltimaAzione.NumeroRiga = 1
GO

