CREATE VIEW [dbo].[Agronica_Log_Pua_UltimaOperazione] AS

    WITH CTE AS (
        SELECT * ,ROW_NUMBER() OVER (PARTITION BY Tipo, Chiave ORDER BY Data_Ora_RegistrazioneLog DESC, ID DESC) AS NumeroRiga
        FROM [dbo].[Agronica_Log_Pua]
    )

    SELECT UltimaAzione.SuperUser AS SuperUser, UltimaAzione.Utente,
            ISNULL(UltimaAzione.Tipo,'') AS Tipo, ISNULL(UltimaAzione.Chiave,'') AS Chiave, 
            UltimaAzione.Param1, UltimaAzione.Param2, UltimaAzione.Param3, UltimaAzione.Param4, UltimaAzione.Param5, UltimaAzione.Param6,
             UltimaAzione.Param7, UltimaAzione.Param8, UltimaAzione.Param9, UltimaAzione.Param10,
            UltimaAzione.Data_Ora_RegistrazioneLog, UltimaAzione.Note, 
    (CASE 
        WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_operazione IS NULL THEN 1 --'INSERT'
        WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_operazione = 3 THEN 2 --'MODIFICA'
        WHEN UltimaAzione.Tipo_Operazione = 2 THEN 2 --'MODIFICA DIRETTA'
        WHEN UltimaAzione.Tipo_Operazione = 3 THEN 3 --'DELETE'
        ELSE UltimaAzione.Tipo_Operazione
    END
    ) As UltimaOperazione
    FROM CTE UltimaAzione
    LEFT JOIN CTE PenultimaAzione ON PenultimaAzione.Tipo = UltimaAzione.Tipo AND PenultimaAzione.Chiave = UltimaAzione.Chiave AND PenultimaAzione.NumeroRiga = 2
    WHERE UltimaAzione.NumeroRiga = 1

GO

   
/*********************************************************************************/
/******       VISTA [GIASMVV]    ******/
/*********************************************************************************/
PRINT ('nuova VISTA: GIASMVV')

IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[GIASMVV]'))
    DROP VIEW [dbo].[GIASMVV]
GO
CREATE VIEW [dbo].[GIASMVV] AS

    SELECT 
      a.PIVA
    , a.Id_Agenda
    , a.Lav_Cod
    , a.des_lib
    , Mov_Dett_Magazzino.Id_Mov_Det
    , Mov_Dett_Magazzino.Mov_Det_Des
    , coalesce(Mov_Dett_Magazzino.Extra_Str, '') as Mov_Det_Des_Extra
        , Mov_Contabile.Colli as Mov_C_Colli
    , coalesce(Mov_Contabile.Extra_Str, '') as Note
    , Mov_Contabile.Modalita as Mov_C_Modalita
    , Mov_Contabile.Mezzo as Mov_C_Mezzo
    , Mov_Contabile.Cod_Vettore as Mov_C_Cod_Vettore
    , Mov_Contabile.Cod_IndirizzoVettore as Mov_C_Cod_IndirizzoVettore
    , Mov_Contabile.Data_Modifica as Data_Riferimento
    , Mov_Contabile.Cod_Destinazione as Mov_C_Cod_destinazione
    
    , Mov_Dett_Magazzino.Qta * Mov_Dett_Magazzino.QTA_EXTRA  as peso
    , Mov_Dett_Magazzino.mat_cod
    , ISNULL ((
        select top 1 codice_generazione from OGenerazioni_Anagrafe_Log og
        where og.Piva = a.PIVA and og.Mat_Cod = Mov_Dett_Magazzino.Mat_Cod 
        order by og.ID_Generazione desc
      ),0) as codice_generazione

    , Mov_Dett_Magazzino.Lotto
    , Mov_Dett_Magazzino.Cal_Cod
    , Mov_Dett_Magazzino.Udm_Cod
    , Mov_Dett_Magazzino.Qta
    , Mov_Dett_Magazzino.Tara as Mov_Dett_Magazzino_Tara
    , Mov_Dett_Magazzino.UDM_COD_EXTRA
    , Mov_Dett_Magazzino.QTA_EXTRA
    , Mov_Dett_Magazzino.Qta_Extra_Totale
    , materie.Mat_Des as Denominazione_Origine
    , materie.Mat_Des as Descrizione_commerciale
    , coalesce(materie.Cod_Articolo, '') as Cod_Articolo
    , coalesce(materie.categoria_vino_cod , 0) as  categoria_vino_cod
    , materie.qta_extra as CapacitaImballo
    , coalesce(materie.udm_cod,0) as udm_cod_mp
    , coalesce(materie.udm_cod_extra,0) as udm_cod_extra_mp

    , Dettagli_Extra.Sa_Cod
    , Dettagli_Extra.Codice_Prodotto as Extra_Codice_Prodotto
    , Dettagli_Extra.Colore as Extra_Colore
    , Dettagli_Extra.Marche_Contenitori as Extra_Marche_Contenitori
    , Dettagli_Extra.Num_Contenitori as Extra_Num_Contenitori
    , Dettagli_Extra.Des_Contenitori as Extra_Des_Contenitori
    , Dettagli_Extra.Zona_Viticola  collate SQL_Latin1_General_CP850_CI_AS as Extra_Zona_Viticola
    , Dettagli_Extra.Manipolazioni as Extra_Manipolazioni
    , Dettagli_Extra.Precisazioni as Extra_Precisazioni
    , coalesce(Dettagli_extra.Titolo_Alcol,0) as Extra_Titolo_Alcol 
    , coalesce( case when materie.Codice_NC is null then  Dettagli_Extra.Codice_NC else materie.Codice_NC  end, '-1') as Codice_NC
    , Movimento_Extra.Peso_Lordo as Extra_Peso_Lordo
    , Movimento_Extra.Num_Colli as Extra_Num_Colli
    , Movimento_Extra.Id_Cod_Autorita

    , Movimento_Extra.Peso AS Peso_2
    , Movimento_Extra.Id_Reg_Dettaglio AS Id_Movimento_Extra
    , Movimento_Extra.Luogo_Partenza
    , Movimento_Extra.Data_Spedizione
    , Movimento_Extra.Num_Riferimento
    , Movimento_Extra.Data_Dichiarazione
    , Movimento_Extra.Garanzia
    , Movimento_Extra.Certificati
    , Movimento_Extra.Durata_Viaggio
    , Movimento_Extra.Tipo_Trasporto
    , movimento_Extra.Unita_Trasporto 

    , coalesce(UnitaMisura.UDM_DES,'') as Udm_Des
    , coalesce(UnitaMisura.UDM_SIM, '') as Udm_Sim
    , coalesce(UnitaMisura_Extra.UDM_DES,'') as UDM_DES_EXTRA
    , coalesce(UnitaMisura_Extra.UDM_SIM,'') as Udm_Sim_Extra

     ,coalesce(unitamisura_materiaPrima.udm_des,'') as UDM_DES_Materie_Prime
     ,coalesce(unitamisura_materiaPrima.udm_SIM,'') as UDM_SIM_Materie_Prime
     ,coalesce(unitamisura_extra_materiaPrima.UDM_DES,'') as UDM_DES_EXTRA_Materie_Prime
     ,coalesce(unitamisura_extra_materiaPrima.udm_SIM,'') as UDM_SIM_EXTRA_Materie_Prime

    , coalesce(movimento_Extra.Annotazioni, 0) as FlagArt29

    -- Speditore
    , imprese_Speditore.PIVa as Speditore_CodiceSoggetto
    , imprese_Speditore.rag_soc as Speditore_Denominazione
    , Indirizzi_Speditore.ind_des AS Speditore_Indirizzo
    , ISNULL(Indirizzi_Speditore.frz_des, '') AS Speditore_Frazione
    , Indirizzi_Speditore.CAP AS Speditore_CAP
    , Indirizzi_Speditore.stato  collate SQL_Latin1_General_CP850_CI_AS AS Speditore_Stato
    , ISTAT_Speditore.LOCALITA AS Speditore_Localita
    , ISNULL(Indirizzi_Speditore.frz_des, '') + ' ' + ISTAT_Speditore.LOCALITA + ' ' + ISTAT_Speditore.COMUNI_PROV AS Speditore_Comune_Provincia
    , 'IT' collate SQL_Latin1_General_CP850_CI_AS  as Speditore_Lingua
    , Indirizzi_Speditore.pro_cod as Speditore_Provincia
    , coalesce(ISTAT_Speditore.Prov, '') as Speditore_Provincia_Istat
    , coalesce(ISTAT_Speditore.Com, '') as Speditore_Comune_Istat
    
    , imprese_Speditore.rag_soc as Denominazione_LuogoSpedizione
    , Indirizzi_Speditore.ind_des AS ind_des_LuogoSpedizione
    , ISNULL(Indirizzi_Speditore.frz_des, '') AS frz_des_LuogoSpedizione
    , Indirizzi_Speditore.CAP AS cap_LuogoSpedizione
    , Indirizzi_Speditore.stato  collate SQL_Latin1_General_CP850_CI_AS AS stato_LuogoSpedizione
    , ISTAT_Speditore.LOCALITA AS localita_LuogoSpedizione
    , ISNULL(Indirizzi_Speditore.frz_des, '') + ' ' + ISTAT_Speditore.LOCALITA + ' ' + ISTAT_Speditore.COMUNI_PROV AS comuni_prov_LuogoSpedizione
    , 'IT' collate SQL_Latin1_General_CP850_CI_AS as Codice_Lingua_LuogoSpedizione
    , COALESCE(Contatti_Codici_Speditore_CodiceAccisa.Val_cod, '') as Speditore_CodiceAccisa

    -- destinatario
    , coalesce(Contatti_Destinatario.Cod_Contatto,'') AS Cod_Contatto_Cliente
    , coalesce(Contatti_Destinatario.Cod_Contatto,'') AS Destinatario_CodiceSoggetto
    , Contatti_Destinatario.Rag_Soc AS Destinatario_Rag_Soc
    , Contatti_Destinatario.Codice_Fiscale AS Destinatario_Codice_Fiscale
    , Contatti_Destinatario.Id_Cf AS Destinatario_Id_CF
    , Contatti_Destinatario.Nome AS Destinatario_Nome
    , Contatti_Destinatario.Cognome AS Destinatario_Cognome
    , Indirizzi_Destinatario.ind_des AS Destinatario_Indirizzo
    , Indirizzi_Destinatario.frz_des AS Destinatario_Frazione
    , Indirizzi_Destinatario.CAP AS Destinatario_CAP
    , Indirizzi_Destinatario.stato  collate SQL_Latin1_General_CP850_CI_AS AS Destinatario_Stato 
    , Istat_Destinatario.LOCALITA AS Destinatario_Localita
    , coalesce (Indirizzi_Destinatario.frz_des, '') 
        + ' '  
        + case when Istat_Destinatario.LOCALITA = 'Non Definita' then ''
          else coalesce(Istat_Destinatario.LOCALITA, '')
        end
        + ' ' 
        + case when Istat_Destinatario.COMUNI_PROV = '00' then ''
            else coalesce(Istat_Destinatario.COMUNI_PROV, '')
        end AS Destinatario_Comune_Provincia
    , coalesce(Istat_Destinatario.Prov, '') as Destinatario_Provincia
    , coalesce(Istat_Destinatario.Com, '') as Destinatario_Comune
    , coalesce(Contatti_Codici_Destinatario_CodiceAccisa.Val_Cod, '') as Destinatario_CodiceAccisa

    -- Acquirente
    , case when Movimento_Extra.accdaa_cod_risum_destinatario is null then 0
        when Movimento_Extra.accdaa_cod_risum_destinatario = 0 then 0
        else 1 end as Acquirente_Specified
    , coalesce(Contatti_Acquirente.Cod_Contatto,'') AS Cod_Contatto_Acquirente
    , coalesce(Contatti_Acquirente.Cod_Contatto,'') AS Acquirente_CodiceSoggetto
    , Contatti_Acquirente.Rag_Soc AS Acquirente_Rag_Soc
    , Contatti_Acquirente.Codice_Fiscale AS Acquirente_Codice_Fiscale
    , Contatti_Acquirente.Id_Cf AS Acquirente_Id_CF
    , Contatti_Acquirente.Nome AS Acquirente_Nome
    , Contatti_Acquirente.Cognome AS Acquirente_Cognome
    , Indirizzi_Acquirente.ind_des AS Acquirente_Indirizzo
    , Indirizzi_Acquirente.frz_des AS Acquirente_Frazione
    , Indirizzi_Acquirente.CAP AS Acquirente_CAP
    , Indirizzi_Acquirente.stato  collate SQL_Latin1_General_CP850_CI_AS AS Acquirente_Stato 
    , Istat_Acquirente.LOCALITA AS Acquirente_Localita
    , coalesce (Indirizzi_Acquirente.frz_des, '') 
        + ' '  
        + case when Istat_Acquirente.LOCALITA = 'Non Definita' then ''
          else coalesce(Istat_Acquirente.LOCALITA, '')
        end
        + ' ' 
        + case when Istat_Acquirente.COMUNI_PROV = '00' then ''
            else coalesce(Istat_Acquirente.COMUNI_PROV, '')
        end AS Acquirente_Comune_Provincia
    , coalesce(Istat_Acquirente.Prov, '') as Acquirente_Provincia
    , coalesce(Istat_Acquirente.Com, '') as Acquirente_Comune
    , coalesce(Contatti_Codici_Acquirente_CodiceAccisa.Val_Cod, '') as Acquirente_CodiceAccisa

    -- Venditore
    , case when Movimento_Extra.accdaa_cod_risum_destinazione is null then 0
        when Movimento_Extra.accdaa_cod_risum_destinazione = 0 then 0
        else 1 end as Venditore_Specified
    , coalesce(Contatti_Venditore.Cod_Contatto,'') AS Cod_Contatto_Venditore
    , coalesce(Contatti_Venditore.Cod_Contatto,'') AS Venditore_CodiceSoggetto
    , Contatti_Venditore.Rag_Soc AS Venditore_Rag_Soc
    , Contatti_Venditore.Codice_Fiscale AS Venditore_Codice_Fiscale
    , Contatti_Venditore.Id_Cf AS Venditore_Id_CF
    , Contatti_Venditore.Nome AS Venditore_Nome
    , Contatti_Venditore.Cognome AS Venditore_Cognome
    , Indirizzi_Venditore.ind_des AS Venditore_Indirizzo
    , Indirizzi_Venditore.frz_des AS Venditore_Frazione
    , Indirizzi_Venditore.CAP AS Venditore_CAP
    , Indirizzi_Venditore.stato  collate SQL_Latin1_General_CP850_CI_AS AS Venditore_Stato 
    , Istat_Venditore.LOCALITA AS Venditore_Localita
    , coalesce (Indirizzi_Venditore.frz_des, '') 
        + ' '  
        + case when Istat_Venditore.LOCALITA = 'Non Definita' then ''
          else coalesce(Istat_Venditore.LOCALITA, '')
        end
        + ' ' 
        + case when Istat_Venditore.COMUNI_PROV = '00' then ''
            else coalesce(Istat_Venditore.COMUNI_PROV, '')
        end AS Venditore_Comune_Provincia
    , coalesce(Istat_Venditore.Prov, '') as Venditore_Provincia
    , coalesce(Istat_Venditore.Com, '') as Venditore_Comune
    , coalesce(Contatti_Codici_Venditore_CodiceAccisa.Val_Cod, '') as Venditore_CodiceAccisa


    -- destinatario diverso
    , COALESCE(Contatti_Destinatario_Diverso.Rag_Soc,'') AS Destinatario_Diverso_Rag_Soc
    , COALESCE(Contatti_Destinatario_Diverso.Codice_Fiscale,'') AS Destinatario_Diverso_Codice_Fiscale
    , coalesce(Contatti_Destinatario_Diverso.Cod_Contatto,'') AS Destinatario_Diverso_CodiceSoggetto
    , COALESCE(Contatti_Destinatario_Diverso.Id_Cf,0) AS Destinatario_Diverso_Id_CF
    , COALESCE(Contatti_Destinatario_Diverso.Nome,'') AS Destinatario_Diverso_Nome
    , COALESCE(Contatti_Destinatario_Diverso.Cognome,'') AS Destinatario_Diverso_Cognome
    , COALESCE(Indirizzi_Destinatario_Diverso.ind_des,'') AS Destinatario_Diverso_Indirizzo
    , COALESCE(Indirizzi_Destinatario_Diverso.frz_des,'') AS Destinatario_Diverso_Frazione
    , COALESCE(Indirizzi_Destinatario_Diverso.CAP,'') AS Destinatario_Diverso_CAP
    , COALESCE(Indirizzi_Destinatario_Diverso.stato  collate SQL_Latin1_General_CP850_CI_AS,'') AS Destinatario_Diverso_Stato 
    , COALESCE(Istat_Destinatario_Diverso.LOCALITA,'') AS Destinatario_Diverso_Localita
    ,coalesce( Istat_Destinatario_Diverso.LOCALITA + ' ' + Istat_Destinatario_Diverso.COMUNI_PROV, '') AS Destinatario_Diverso_Comune_Provincia
    , coalesce(Istat_Destinatario_Diverso.Prov, '') as Destinatario_Diverso_Provincia
    , coalesce(Istat_Destinatario_Diverso.Com, '') as Destinatario_Diverso_Comune
    , coalesce(Contatti_Codici_Destinatario_Diverso_CodiceAccisa.Val_Cod, '') as Destinatario_Diverso_CodiceAccisa
    -- luogo consegna
    , Movimento_Extra.Luogo_Consegna
    , case when isnumeric( Movimento_Extra.Luogo_Consegna) = 1 then 
        case when Movimento_Extra.Luogo_Consegna = 0 then 0
            when Movimento_Extra.Luogo_Consegna = -1 then 0
            else 1 end
    else 0 end as Cod_Indirizzo_Consegna_Specified 
    
    -- vettore
    , ISNULL(Contatti_Vettore.Cod_Contatto, '') AS Vettore_CodContatto
    , ISNULL(Contatti_Vettore.Cod_Contatto, '') AS Vettore_CodiceSoggetto
    , COALESCE(Contatti_Vettore.Id_Cf,0) AS Vettore_Id_CF
    , ISNULL(Contatti_Vettore.Rag_Soc, '') AS Vettore_Denominazione
    , ISNULL(Contatti_Vettore.Codice_Fiscale, '') AS Vettore_CodiceFiscale
    , ISNULL(Contatti_Vettore.Nome, '') AS Vettore_Nome
    , ISNULL(Contatti_Vettore.Cognome, '') AS Vettore_Cognome
    , ISNULL(Indirizzi_Vettore.ind_des, '') AS Vettore_Indirizzo
    , ISNULL(Indirizzi_Vettore.frz_des, '') AS Vettore_Frazione
    , ISNULL(Indirizzi_Vettore.CAP, '') AS Vettore_CAP
    , ISNULL(Indirizzi_Vettore.stato, '') AS Vettore_Stato
    , ISNULL(Istat_Vettore.LOCALITA, '') AS Vettore_Localita
    , coalesce(case when Indirizzi_Vettore.com_cod_istat = 0 then coalesce(Indirizzi_Vettore.frz_des, '') else Istat_Vettore.LOCALITA + ' ' + Istat_Vettore.COMUNI_PROV END, '') as Vettore_Comune_Provincia
    , coalesce(Istat_Vettore.Prov, '') as Vettore_Provincia
    , coalesce(Istat_Vettore.Com, '') as Vettore_Comune

    -- Conducente
    , coalesce(Movimento_Extra.trasportatore, '') as Conducente_Cognome_Nome

    -- registro vino
    , coalesce(registrovino.CodStatoFisico, '') as Reg_V_CodStatoFisico
    , coalesce( RegistroVino.CodCategoria,'') as Reg_V_CodCategoria
    , coalesce( RegistroVino.CodClassificazione,'') as Reg_V_CodClassificazione
    , coalesce(RegistroVino.CodColore,'') as Reg_V_CodColore
    , coalesce(RegistroVino.AttoCert,'') as Reg_V_AttoCert
    , coalesce(RegistroVino.Annata,'') as Reg_V_Annata
    , coalesce(RegistroVino.PercAnnata,'') as Reg_V_PercAnnata
    , coalesce(RegistroVino.CodEbacchus,'') as Reg_V_CodEbacchus
    , coalesce(RegistroVino.Biologico,'') as Reg_V_Biologico
    , coalesce(RegistroVino.OrigineUve,'') as Reg_V_OrigineUve
    , coalesce(RegistroVino.Provenienza,'') as Reg_V_Provenienza
    , coalesce(RegistroVino.Varieta,'') as Reg_V_Varieta
    , coalesce(RegistroVino.Altrevarieta,'') as Reg_V_Altrevarieta
    , coalesce(RegistroVino.Menzioni,'') as Reg_V_Menzioni
    , coalesce(RegistroVino.CodZonaViticola,'') as Reg_V_CodZonaViticola
    , coalesce(RegistroVino.CodDopIgp, '') as Reg_V_CodDopIgp
    , coalesce(RegistroVino.VolNominale, 0) as Reg_V_CapacitaImballo
    , coalesce(RegistroVino.designazione, '') as Reg_V_Designazione
    , coalesce(RegistroVino.praticheenologiche, '') as Reg_V_PraticheEno
    , coalesce(RegistroVino.titoloAlcolPot, 0) as Reg_V_TitoloAlcolPot
    , coalesce(RegistroVino.titoloAlcolTot, 0) as Reg_V_TitoloAlcolTot
    , coalesce(RegistroVino.titoloAlcolEff, 0) as Reg_V_TitoloAlcolEff
    , coalesce(RegistroVino.Lotto, '') as Reg_V_Lotto
    , coalesce(RegistroVino.CodSottozona, '') as Reg_V_CodSottozona
    , coalesce(RegistroVino.CodVigna, '') as Reg_V_CodVigna
    , coalesce(RegistroVino.CodPartita, '') as Reg_V_CodPartita
    , coalesce(RegistroVino.MassaVolumica, 0) as Reg_V_MassaVolumica
    , coalesce(RegistroVino.NumcertDop, '') as Reg_V_NumcertDop
    , RegistroVino.DataCertDop as Reg_V_DataCertDop
    , coalesce(RegistroVino.PaesiProvenienza, '') as Reg_V_PaesiProvenienza
    , coalesce(RegistroVino.CodTenoreZucchero, '') as Reg_V_CodTenoreZucchero
    , coalesce(RegistroVino.VolNominale, 0) as Reg_V_VolNominale

    , coalesce(Dettagli_Extra.num_colli,0) as NumeroColli
    , coalesce(Dettagli_Extra.des_contenitori , '') as DesColli
    , coalesce(Dettagli_Extra.num_contenitori,0) as NumeroImballi
    , coalesce(Dettagli_Extra.marche_contenitori ,'') as DesImballi

    , coalesce(Movimento_Extra.Luogo_Partenza,'') as LuogoSpedizione
    
    -- mezzo trasporto
     ,Movimento_Extra.Mezzo_Trasporto as MezzoTrasporto_Mezzo
    , coalesce(case when Movimento_Extra.Targa = '' then  Movimento_Extra.Mezzo_Trasporto else Movimento_Extra.Targa  end, '') AS MezzoTrasporto_Targa
    , Movimento_Extra.N_Immatricolazione AS MezzoTrasporto_Immatricolazione
    , coalesce(Movimento_Extra.N_Immatricolazione_Rimorchio,'') AS MezzoTrasporto_Immatricolazione2
    , Movimento_Extra.Tipo_Trasporto as MezzoTrasporto_Tipo
    , coalesce(movimento_Extra.Unita_Trasporto, -1) as MezzoTrasporto_Codice_Unita
    , coalesce(unita_trasporto.Descrizione,'') as MezzoTrasporto_Unita
    , coalesce(Mov_Contabile.Causale_Trasporto,'') as CausaleTrasporto
    , coalesce(Movimento_Extra.N_Autorizzazione_Trasporto, '') as MezzoTrasporto_Num_Aut
    , coalesce(Movimento_Extra.Data_Rilascio_Autorizzazione, '1900-01-01') as MezzoTrasporto_Data_Aut

    -- dati documento
    , Mov_Contabile.Data_Movimento as Documento_DataDocumento
    , cast(Mov_Contabile.Doc_Numero_Sin as nvarchar(255)) collate SQL_Latin1_General_CP850_CI_AS as Documento_Doc_Numero_Sin 
    , cast(Mov_Contabile.Doc_Numero as nvarchar(255)) collate SQL_Latin1_General_CP850_CI_AS as Documento_Doc_Numero
    , cast(Mov_Contabile.Doc_Numero_Des as nvarchar(255)) collate SQL_Latin1_General_CP850_CI_AS  as Documento_Doc_Numero_Des
    , coalesce(Mov_Contabile.Ora, '1900-01-01') as Documento_Ora
    , Mov_Contabile.Doc_Numero

    -- autorita competente spedizione
    , COALESCE(Indirizzo_Aut_Competente.ind_des,'') AS Autorita_Competente_Indirizzo
    , COALESCE(Indirizzo_Aut_Competente.frz_des,'') AS Autorita_Competente_Frazione
    , COALESCE(Indirizzo_Aut_Competente.CAP,'') AS Autorita_Competente_CAP
    , COALESCE(Indirizzo_Aut_Competente.stato  collate SQL_Latin1_General_CP850_CI_AS,'') AS Autorita_Competente_Stato 
    , COALESCE(Istat_Autorita_Competente.LOCALITA,'') AS Autorita_Competente_Localita
    , coalesce(ISNULL(Indirizzo_Aut_Competente.frz_des, '') + ' ' + Istat_Autorita_Competente.LOCALITA + ' ' + Istat_Autorita_Competente.COMUNI_PROV, '') AS Autorita_Competente_Comune_Provincia
    , coalesce(cac.val_cod,'') as UfficioICQRF

    , coalesce(cac2.val_cod,'') as CodiceICQRF

    , case when lpx.CodZonaViticola is NULL then '' else
        case 
            when lpx.CodZonaViticola = '0' then '' else lpx.CodZonaViticola end 
        end as CodZonaViticola_Linea

    , coalesce(gen.zona_viticola, '') as CodZonaViticola_Gen

    FROM   agenda a
    INNER JOIN Movimenti as Mov_Contabile ON a.PIVA = Mov_Contabile.PIVA 
        AND a.Sa_Cod = Mov_Contabile.Sa_Cod 
        AND a.Id_Agenda = Mov_Contabile.Id_Agenda 

        --Dettagli MVV
    INNER JOIN Movimenti AS Mov_Magazzino ON a.PIVA = Mov_Magazzino.PIVA 
        AND a.Sa_Cod = Mov_Magazzino.Sa_Cod 
        AND a.Id_Agenda = Mov_Magazzino.Id_Agenda

        INNER JOIN Movimenti_Dettagli AS Mov_Dett_Magazzino ON Mov_Magazzino.PIVA = Mov_Dett_Magazzino.PIVA 
        AND Mov_Magazzino.Id_Agenda = Mov_Dett_Magazzino.Id_Agenda
        AND Mov_Magazzino.Id_Mov = Mov_Dett_Magazzino.Id_Mov 

    INNER JOIN Materie_Prime Materie on Materie.mat_cod = Mov_Dett_Magazzino.Mat_Cod 

    INNER JOIN Mov_Dettaglio_Tecnico_Extra AS Dettagli_Extra ON Dettagli_Extra.PIVA = Mov_Dett_Magazzino.PIVA 
            AND Dettagli_Extra.Sa_Cod = Mov_Dett_Magazzino.Sa_Cod
            AND Dettagli_Extra.Id_Agenda = Mov_Dett_Magazzino.Id_Agenda 
            AND Dettagli_Extra.Id_Mov = Mov_Dett_Magazzino.Id_Mov 
            AND Dettagli_Extra.Id_Mov_Det = Mov_Dett_Magazzino.Id_Mov_Det
            
    INNER JOIN Mov_Dettaglio_Tecnico_Extra AS Movimento_Extra ON Movimento_Extra.PIVA = Mov_Contabile.PIVA 
            AND Movimento_Extra.Sa_Cod = Mov_Contabile.Sa_Cod
            AND Movimento_Extra.Id_Agenda = Mov_Contabile.Id_Agenda 
            AND Movimento_Extra.Id_Mov = Mov_Contabile.Id_Mov 
            and Movimento_Extra.id_mov_det = 0 

    INNER JOIN UnitaMisura ON UnitaMisura.Udm_Cod = Mov_Dett_Magazzino.Udm_Cod 
    LEFT jOIN UnitaMisura as UnitaMisura_Extra
        on Mov_Dett_Magazzino.UDM_COD_EXTRA = UnitaMisura_Extra.UDM_COD

    left join unitamisura as unitamisura_materiaPrima on unitamisura_materiaPrima.udm_cod = materie.udm_cod
    left join UnitaMisura as unitamisura_extra_materiaPrima on unitamisura_extra_materiaPrima.udm_cod = materie.Udm_Cod_Extra

    --Speditore
    INNER JOIN Imprese imprese_Speditore
        on imprese_Speditore.piva = a.PIVA 
        
    INNER JOIN ImpresexIndirizzi IMPIndirizzi_Speditore
        on IMPIndirizzi_Speditore.piva = a.PIVA 
        
    INNER JOIN Indirizzi AS Indirizzi_Speditore 
        ON Indirizzi_Speditore.cod_indirizzo = impIndirizzi_Speditore.cod_indirizzo
        
    INNER join ISTAT as ISTAT_Speditore on Indirizzi_Speditore.pro_cod_istat = ISTAT_Speditore.PROV 
        AND Indirizzi_Speditore.com_cod_istat = ISTAT_Speditore.COM 
    
    
    INNER JOIN Contatti as Contatti_Speditore  
        ON Contatti_Speditore.Cod_Contatto  = imprese_Speditore.PIVA 
        
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore 
        ON Contatti_codici_Speditore.PIVA = Contatti_Speditore.PIVA
        AND Contatti_Codici_Speditore.Cod_Contatto = Contatti_Speditore.Cod_Contatto
    
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore_CodMagazzino 
        ON Contatti_Codici_Speditore_CodMagazzino.PIVA = Contatti_Speditore.PIVA
        AND Contatti_Codici_Speditore_codMagazzino.Cod_Contatto = Contatti_Speditore.Cod_Contatto
    
        
    --Autorit? fiscale competente sul luogo di spedizione   Autorit? fiscale competente sul luogo di spedizione (31)
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore_UfficioSpedizioneImportazione 
        ON Contatti_Codici_Speditore_UfficioSpedizioneImportazione.PIVA = Contatti_Speditore.PIVA
        AND Contatti_Codici_Speditore_UfficioSpedizioneImportazione.Cod_Contatto = Contatti_Speditore.Cod_Contatto

    -- Codice Accisa Speditore
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore_CodiceAccisa
        on Contatti_Codici_Speditore_CodiceAccisa.PIVA = Contatti_Speditore.Piva
        and Contatti_Codici_Speditore_CodiceAccisa.Cod_Contatto = Contatti_Codici_Speditore_CodiceAccisa.PIVA
        and Contatti_Codici_Speditore_CodiceAccisa.Id_cod = 4003

        --Azienda di trasporto  Azienda di trasporto (52 --> 65)
    LEFT OUTER JOIN Risorse_Umane AS Risorse_Umane_Vettore 
        ON Mov_Contabile.Cod_Vettore = Risorse_Umane_Vettore.Cod_RisUm 
        
    LEFT OUTER JOIN Contatti AS Contatti_Vettore 
        ON Risorse_Umane_Vettore.Piva = Contatti_Vettore.Piva 
        AND Risorse_Umane_Vettore.Cod_Contatto = Contatti_Vettore.Cod_Contatto 
        
    LEFT OUTER JOIN Indirizzi AS Indirizzi_Vettore 
        ON Mov_Contabile.Cod_IndirizzoVettore = Indirizzi_Vettore.cod_indirizzo 
    
    LEFT OUTER JOIN ISTAT AS Istat_Vettore 
        ON Indirizzi_Vettore.pro_cod_istat = Istat_Vettore.PROV 
        AND Indirizzi_Vettore.com_cod_istat = Istat_Vettore.COM

    LEFT JOIN ACCDAA_ANAG_T009_TabellaCodiciUnitaDiTrasporto as unita_trasporto
        on movimento_Extra.Unita_Trasporto = unita_trasporto.Codice

    LEFT JOIN ws_RegVino_Prodotti AS RegistroVino
        on Mov_Dett_Magazzino.PIVA = RegistroVino.PIVA
        and Mov_Dett_Magazzino.Mat_Cod = RegistroVino.Mat_Cod
        and Mov_Dett_Magazzino.Lotto = RegistroVino.Lotto
    
    -- *****************************************************************************
    -- acquirente 

    LEFT JOIN Risorse_Umane as Risorse_Umane_Acquirente 
            ON Movimento_Extra.accdaa_cod_risum_destinatario = Risorse_Umane_Acquirente.Cod_RisUm 

    LEFT JOIN Contatti as Contatti_Acquirente
        ON Risorse_Umane_Acquirente.Piva = Contatti_Acquirente.Piva 
        AND Risorse_Umane_Acquirente.Cod_Contatto = Contatti_Acquirente.Cod_Contatto 

    LEFT JOIN Indirizzi AS Indirizzi_Acquirente
        ON Movimento_Extra.accdaa_cod_indirizzorisum_destinatario = Indirizzi_Acquirente.cod_indirizzo 

    LEFT JOIN ISTAT AS Istat_Acquirente
        ON Indirizzi_Acquirente.pro_cod_istat = Istat_Acquirente.PROV 
        AND Indirizzi_Acquirente.com_cod_istat = Istat_Acquirente.COM 

    LEFT JOIN Contatti_Codici AS Contatti_Codici_Acquirente_CodiceAccisa
        on Contatti_Codici_Acquirente_CodiceAccisa.PIVA = Contatti_Acquirente.Piva
        and Contatti_Codici_Acquirente_CodiceAccisa.Cod_Contatto = Contatti_Acquirente.Cod_Contatto
        and Contatti_Codici_Acquirente_CodiceAccisa.Id_cod = 4003

    -- *****************************************************************************
    -- venditore 
    LEFT JOIN Risorse_Umane as Risorse_Umane_Venditore 
            ON Movimento_Extra.accdaa_cod_risum_destinazione = Risorse_Umane_Venditore.Cod_RisUm 

    LEFT JOIN Contatti as Contatti_Venditore
        ON Risorse_Umane_Venditore.Piva = Contatti_Venditore.Piva 
        AND Risorse_Umane_Venditore.Cod_Contatto = Contatti_Venditore.Cod_Contatto 

    LEFT JOIN Indirizzi AS Indirizzi_Venditore
        ON Movimento_Extra.accdaa_cod_indirizzorisum_destinazione = Indirizzi_Venditore.cod_indirizzo 

    LEFT JOIN ISTAT AS Istat_Venditore
        ON Indirizzi_Venditore.pro_cod_istat = Istat_Venditore.PROV 
        AND Indirizzi_Venditore.com_cod_istat = Istat_Venditore.COM 

    LEFT JOIN Contatti_Codici AS Contatti_Codici_Venditore_CodiceAccisa
        on Contatti_Codici_Venditore_CodiceAccisa.PIVA = Contatti_Venditore.Piva
        and Contatti_Codici_Venditore_CodiceAccisa.Cod_Contatto = Contatti_Venditore.Cod_Contatto
        and Contatti_Codici_Venditore_CodiceAccisa.Id_cod = 4003


    -- *****************************************************************************
    -- destinatario
    INNER JOIN Risorse_Umane as Risorse_Umane_Destinatario 
            ON Mov_Contabile.Cod_RisUm = Risorse_Umane_Destinatario.Cod_RisUm 
            
    INNER JOIN Contatti as Contatti_Destinatario 
        ON Risorse_Umane_Destinatario.Piva = Contatti_Destinatario.Piva 
        AND Risorse_Umane_Destinatario.Cod_Contatto = Contatti_Destinatario.Cod_Contatto 
    
    INNER JOIN Indirizzi AS Indirizzi_Destinatario 
        ON Mov_Contabile.Cod_IndirizzoRisUm = Indirizzi_Destinatario.cod_indirizzo 
    
    INNER JOIN ISTAT AS Istat_Destinatario 
        ON Indirizzi_Destinatario.pro_cod_istat = Istat_Destinatario.PROV 
        AND Indirizzi_Destinatario.com_cod_istat = Istat_Destinatario.COM 

    -- Codice Accisa  Destinatario
    LEFT JOIN Contatti_Codici AS Contatti_Codici_Destinatario_CodiceAccisa
        on Contatti_Codici_Destinatario_CodiceAccisa.PIVA = Contatti_Destinatario.Piva
        and Contatti_Codici_Destinatario_CodiceAccisa.Cod_Contatto = Contatti_Destinatario.Cod_Contatto
        and Contatti_Codici_Destinatario_CodiceAccisa.Id_cod = 4003
            
    -- destinatario diverso
    left JOIN Risorse_Umane as Risorse_Umane_Destinatario_Diverso
            ON Mov_Contabile.Cod_Destinazione = Risorse_Umane_Destinatario_Diverso.Cod_RisUm 
            
    LEFT JOIN Contatti as Contatti_Destinatario_Diverso 
        ON Risorse_Umane_Destinatario_Diverso.Piva = Contatti_Destinatario_Diverso.Piva 
        AND Risorse_Umane_Destinatario_Diverso.Cod_Contatto = Contatti_Destinatario_Diverso.Cod_Contatto 
    
    LEFT JOIN Indirizzi AS Indirizzi_Destinatario_Diverso 
        ON Mov_Contabile.Cod_IndirizzoDestinazione = Indirizzi_Destinatario_Diverso.cod_indirizzo 
    
    LEFT JOIN ISTAT AS Istat_Destinatario_Diverso 
        ON Indirizzi_Destinatario_Diverso.pro_cod_istat = Istat_Destinatario_Diverso.PROV 
        AND Indirizzi_Destinatario_Diverso.com_cod_istat = Istat_Destinatario_Diverso.COM 

    LEFT JOIN Contatti_Codici AS Contatti_Codici_Destinatario_Diverso_CodiceAccisa
        on Contatti_Codici_Destinatario_Diverso_CodiceAccisa.PIVA = Contatti_Destinatario_Diverso.Piva
        and Contatti_Codici_Destinatario_Diverso_CodiceAccisa.Cod_Contatto = Contatti_Destinatario_Diverso.Cod_Contatto
        and Contatti_Codici_Destinatario_Diverso_CodiceAccisa.Id_cod = 4003

    -- autorita competente spedizione
    LEFT JOIN Indirizzi as Indirizzo_Aut_Competente
        on Movimento_Extra.Id_Cod_Autorita = Indirizzo_Aut_Competente.cod_indirizzo

    LEFT JOIN ISTAT AS Istat_Autorita_Competente 
        ON Indirizzo_Aut_Competente.pro_cod_istat = Istat_Autorita_Competente.PROV 
        AND Indirizzo_Aut_Competente.com_cod_istat = Istat_Autorita_Competente.COM 

    LEFT JOIN Centri_Aziendali_Codici cac
        on Dettagli_Extra.Piva = cac.PIVA
        and Dettagli_Extra.Sa_Cod = cac.sa_cod
        and cac.id_cod = 1313

    INNER JOIN Centri_Aziendali_Codici cac2
        on Dettagli_Extra.Piva = cac2.PIVA
        and Dettagli_Extra.Sa_Cod = cac2.sa_cod
        and cac2.id_cod = 1109
        and cac2.val_cod= RegistroVino.CodIcqrf

    LEFT JOIN Linee_Produzioni_Extra lpx on materie.Linea_Cod = lpx.Linea_Cod and Materie.Piva = lpx.Piva
    left join OGenerazioni_Anagrafe_Moduli_Log gen on a.PIVA = gen.Piva and gen.Modulo_Generazione = 1

    where 
    a.Lav_Cod = 1071
    AND Mov_Contabile.Cau_Mov = '4000'
    AND Mov_Magazzino.Cau_Mov = '7350'

    AND Contatti_Codici_Speditore.Id_cod = 4003
    AND (Contatti_Codici_Speditore_CodMagazzino.Id_cod = 4006 and Contatti_Codici_Speditore_CodMagazzino.Val_cod <> '0')
    AND (Contatti_Codici_Speditore_UfficioSpedizioneImportazione.Id_cod = 4005)

GO




/*********************************************************************************/
/******       VISTA [GIASMVVE]    ******/
/*********************************************************************************/
PRINT ('nuova VISTA: GIASMVVE')

IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[GIASMVVE]'))
    DROP VIEW [dbo].[GIASMVVE]
GO
CREATE VIEW [dbo].[GIASMVVE] AS

        SELECT
      a.PIVA
    , a.Id_Agenda
    , a.Lav_Cod
    , a.des_lib
    , Mov_Contabile.Colli as Mov_C_Colli
    , coalesce(Mov_Contabile.Extra_Str, '') as Note
    , Mov_Contabile.Modalita as Mov_C_Modalita
    , Mov_Contabile.Mezzo as Mov_C_Mezzo
    , Mov_Contabile.Cod_Vettore as Mov_C_Cod_Vettore
    , Mov_Contabile.Cod_IndirizzoVettore as Mov_C_Cod_IndirizzoVettore
    , Mov_Contabile.Data_Modifica as Data_Riferimento
    , Mov_Contabile.Cod_Destinazione as Mov_C_Cod_destinazione
    
    -- Speditore
    , imprese_Speditore.rag_soc as Speditore_Denominazione
    , imprese_Speditore.PIVA as Speditore_CodiceSoggetto
    , Indirizzi_Speditore.ind_des AS Speditore_Indirizzo
    , ISNULL(Indirizzi_Speditore.frz_des, '') AS Speditore_Frazione
    , Indirizzi_Speditore.CAP AS Speditore_CAP
    , Indirizzi_Speditore.stato  collate SQL_Latin1_General_CP850_CI_AS AS Speditore_Stato
    , ISTAT_Speditore.LOCALITA AS Speditore_Localita
    , ISNULL(Indirizzi_Speditore.frz_des, '') + ' ' + ISTAT_Speditore.LOCALITA + ' ' + ISTAT_Speditore.COMUNI_PROV AS Speditore_Comune_Provincia
    , 'IT' collate SQL_Latin1_General_CP850_CI_AS  as Speditore_Lingua
    , Indirizzi_Speditore.pro_cod as Speditore_Provincia
    
    , imprese_Speditore.rag_soc as Denominazione_LuogoSpedizione
    , Indirizzi_Speditore.ind_des AS ind_des_LuogoSpedizione
    , ISNULL(Indirizzi_Speditore.frz_des, '') AS frz_des_LuogoSpedizione
    , Indirizzi_Speditore.CAP AS cap_LuogoSpedizione
    , Indirizzi_Speditore.stato  collate SQL_Latin1_General_CP850_CI_AS AS stato_LuogoSpedizione
    , ISTAT_Speditore.LOCALITA AS localita_LuogoSpedizione
    , ISNULL(Indirizzi_Speditore.frz_des, '') + ' ' + ISTAT_Speditore.LOCALITA + ' ' + ISTAT_Speditore.COMUNI_PROV AS comuni_prov_LuogoSpedizione
    , 'IT' collate SQL_Latin1_General_CP850_CI_AS as Codice_Lingua_LuogoSpedizione
    , COALESCE(Contatti_Codici_Speditore_CodiceAccisa.Val_cod, '') as Speditore_CodiceAccisa

    -- destinatario
    , coalesce(Contatti_Destinatario.Cod_Contatto,'') AS Cod_Contatto_Cliente
    , Contatti_Destinatario.Rag_Soc +' '+Contatti_Destinatario.Nome+' '+Contatti_Destinatario.Cognome AS Destinatario
    , Contatti_Destinatario.Rag_Soc AS Destinatario_Rag_Soc
    , Contatti_Destinatario.Codice_Fiscale AS Destinatario_Codice_Fiscale
    , Contatti_Destinatario.Id_Cf AS Destinatario_Id_CF
    , Contatti_Destinatario.Nome AS Destinatario_Nome
    , Contatti_Destinatario.Cognome AS Destinatario_Cognome
    , Indirizzi_Destinatario.ind_des AS Destinatario_Indirizzo
    , Indirizzi_Destinatario.frz_des AS Destinatario_Frazione
    , Indirizzi_Destinatario.CAP AS Destinatario_CAP
    , Indirizzi_Destinatario.stato  collate SQL_Latin1_General_CP850_CI_AS AS Destinatario_Stato 
    , Istat_Destinatario.LOCALITA AS Destinatario_Localita
    , coalesce (Indirizzi_Destinatario.frz_des, '') 
        + ' '  
        + case when Istat_Destinatario.LOCALITA = 'Non Definita' then ''
          else coalesce(Istat_Destinatario.LOCALITA, '')
        end
        + ' ' 
        + case when Istat_Destinatario.COMUNI_PROV = '00' then ''
            else coalesce(Istat_Destinatario.COMUNI_PROV, '')
        end AS Destinatario_Comune_Provincia
    , coalesce(Contatti_Codici_Destinatario_CodiceAccisa.Val_Cod, '') as Destinatario_CodiceAccisa

    -- destinatario diverso
    , COALESCE(Contatti_Destinatario_Diverso.Rag_Soc+' '+Contatti_Destinatario_Diverso.Nome +' '+Contatti_Destinatario_Diverso.Cognome,'') AS Destinatario_Diverso
    , COALESCE(Contatti_Destinatario_Diverso.Rag_Soc,'') AS Destinatario_Diverso_Rag_Soc
    , COALESCE(Contatti_Destinatario_Diverso.Codice_Fiscale,'') AS Destinatario_Diverso_Codice_Fiscale
    , COALESCE(Contatti_Destinatario_Diverso.Id_Cf,0) AS Destinatario_Diverso_Id_CF
    , COALESCE(Contatti_Destinatario_Diverso.Nome,'') AS Destinatario_Diverso_Nome
    , COALESCE(Contatti_Destinatario_Diverso.Cognome,'') AS Destinatario_Diverso_Cognome
    , COALESCE(Indirizzi_Destinatario_Diverso.ind_des,'') AS Destinatario_Diverso_Indirizzo
    , COALESCE(Indirizzi_Destinatario_Diverso.frz_des,'') AS Destinatario_Diverso_Frazione
    , COALESCE(Indirizzi_Destinatario_Diverso.CAP,'') AS Destinatario_Diverso_CAP
    , COALESCE(Indirizzi_Destinatario_Diverso.stato  collate SQL_Latin1_General_CP850_CI_AS,'') AS Destinatario_Diverso_Stato 
    , COALESCE(Istat_Destinatario_Diverso.LOCALITA,'') AS Destinatario_Diverso_Localita
    ,coalesce( Istat_Destinatario_Diverso.LOCALITA + ' ' + Istat_Destinatario_Diverso.COMUNI_PROV, '') AS Destinatario_Diverso_Comune_Provincia

    -- vettore
    , ISNULL(Contatti_Vettore.Cod_Contatto, '') AS Vettore_CodContatto
    , ISNULL(Contatti_Vettore.Rag_Soc, '') AS Vettore_Denominazione
    , ISNULL(Contatti_Vettore.Codice_Fiscale, '') AS Vettore_CodiceFiscale
    , ISNULL(Contatti_Vettore.Nome, '') AS Vettore_Nome
    , ISNULL(Contatti_Vettore.Cognome, '') AS Vettore_Cognome
    , ISNULL(Indirizzi_Vettore.ind_des, '') AS Vettore_Indirizzo
    , ISNULL(Indirizzi_Vettore.frz_des, '') AS Vettore_Frazione
    , ISNULL(Indirizzi_Vettore.CAP, '') AS Vettore_CAP
    , ISNULL(Indirizzi_Vettore.stato, '') AS Vettore_Stato
    , ISNULL(Istat_Vettore.LOCALITA, '') AS Vettore_Localita
    , coalesce(case when Indirizzi_Vettore.com_cod_istat = 0 then coalesce(Indirizzi_Vettore.frz_des, '') else Istat_Vettore.LOCALITA + ' ' + Istat_Vettore.COMUNI_PROV END, '') as Vettore_Comune_Provincia

    -- dati documento
    , Mov_Contabile.Data_Movimento as Documento_DataDocumento

    , case 
        when COALESCE(Mov_Contabile.Doc_Numero_Sin,'')  = '' then Mov_Contabile.Doc_Numero_Sin + REPLICATE('0', 5 - LEN(Mov_Contabile.Doc_Numero)) + CAST(Mov_Contabile.Doc_Numero AS varchar) + Mov_Contabile.Doc_Numero_Des
        ELSE Mov_Contabile.Doc_Numero_Sin + '-' + REPLICATE('0', 5 - LEN(Mov_Contabile.Doc_Numero)) + CAST(Mov_Contabile.Doc_Numero AS varchar) + Mov_Contabile.Doc_Numero_Des
        end as Documento_NumeroDocumento

    , cast(Mov_Contabile.Doc_Numero_Sin as nvarchar(255)) collate SQL_Latin1_General_CP850_CI_AS as Documento_Doc_Numero_Sin 
    , cast(Mov_Contabile.Doc_Numero as nvarchar(255)) collate SQL_Latin1_General_CP850_CI_AS as Documento_Doc_Numero
    , cast(Mov_Contabile.Doc_Numero_Des as nvarchar(255)) collate SQL_Latin1_General_CP850_CI_AS  as Documento_Doc_Numero_Des
    , coalesce(Mov_Contabile.Ora, '1900-01-01') as Documento_Ora
    , Mov_Contabile.Doc_Numero
    , (select top 1 val_cod from Centri_Aziendali_Codici AS cac inner join Mov_Dettaglio_Tecnico_Extra As extra 
       on cac.piva = extra.piva and cac.sa_cod = extra.sa_cod and cac.id_cod=1109 and extra.piva = a.piva and extra.id_agenda = a.id_agenda
       ) AS CodiceICQRF
     
    -- Log MVVE
    , MVV_Log.NumMVV
    , MVV_Log.MarcaTemp
    , MVV_Log.DataGenXML
    , MVV_Log.NomeFileXML
    , MVV_Log.NomeFilePDF
    , MVV_Log.Gias_Status
    , MVV_Log.MVV_Status
    
    FROM   agenda a
    INNER JOIN Movimenti as Mov_Contabile ON a.PIVA = Mov_Contabile.PIVA 
        AND a.Sa_Cod = Mov_Contabile.Sa_Cod 
        AND a.Id_Agenda = Mov_Contabile.Id_Agenda 

    --Dettagli MVV
    INNER JOIN Movimenti AS Mov_Magazzino ON a.PIVA = Mov_Magazzino.PIVA 
        AND a.Sa_Cod = Mov_Magazzino.Sa_Cod 
        AND a.Id_Agenda = Mov_Magazzino.Id_Agenda
        
    --Speditore
    INNER JOIN Imprese imprese_Speditore
        on imprese_Speditore.piva = a.PIVA 
        
    INNER JOIN ImpresexIndirizzi IMPIndirizzi_Speditore
        on IMPIndirizzi_Speditore.piva = a.PIVA 
        
    INNER JOIN Indirizzi AS Indirizzi_Speditore 
        ON Indirizzi_Speditore.cod_indirizzo = impIndirizzi_Speditore.cod_indirizzo
        
    INNER join ISTAT as ISTAT_Speditore on Indirizzi_Speditore.pro_cod_istat = ISTAT_Speditore.PROV 
        AND Indirizzi_Speditore.com_cod_istat = ISTAT_Speditore.COM 
    
    INNER JOIN Contatti as Contatti_Speditore  
        ON Contatti_Speditore.Cod_Contatto  = imprese_Speditore.PIVA 
        
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore 
        ON Contatti_codici_Speditore.PIVA = Contatti_Speditore.PIVA
        AND Contatti_Codici_Speditore.Cod_Contatto = Contatti_Speditore.Cod_Contatto
    
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore_CodMagazzino 
        ON Contatti_Codici_Speditore_CodMagazzino.PIVA = Contatti_Speditore.PIVA
        AND Contatti_Codici_Speditore_codMagazzino.Cod_Contatto = Contatti_Speditore.Cod_Contatto
        
    --Autorità fiscale competente sul luogo di spedizione   Autorit? fiscale competente sul luogo di spedizione (31)
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore_UfficioSpedizioneImportazione 
        ON Contatti_Codici_Speditore_UfficioSpedizioneImportazione.PIVA = Contatti_Speditore.PIVA
        AND Contatti_Codici_Speditore_UfficioSpedizioneImportazione.Cod_Contatto = Contatti_Speditore.Cod_Contatto

    -- Codice Accisa Speditore
    INNER JOIN Contatti_Codici AS Contatti_Codici_Speditore_CodiceAccisa
        on Contatti_Codici_Speditore_CodiceAccisa.PIVA = Contatti_Speditore.Piva
        and Contatti_Codici_Speditore_CodiceAccisa.Cod_Contatto = Contatti_Codici_Speditore_CodiceAccisa.PIVA
        and Contatti_Codici_Speditore_CodiceAccisa.Id_cod = 4003

    --Azienda di trasporto  Azienda di trasporto (52 --> 65)
    LEFT OUTER JOIN Risorse_Umane AS Risorse_Umane_Vettore 
        ON Mov_Contabile.Cod_Vettore = Risorse_Umane_Vettore.Cod_RisUm 
        
    LEFT OUTER JOIN Contatti AS Contatti_Vettore 
        ON Risorse_Umane_Vettore.Piva = Contatti_Vettore.Piva 
        AND Risorse_Umane_Vettore.Cod_Contatto = Contatti_Vettore.Cod_Contatto 
        
    LEFT OUTER JOIN Indirizzi AS Indirizzi_Vettore 
        ON Mov_Contabile.Cod_IndirizzoVettore = Indirizzi_Vettore.cod_indirizzo 
    
    LEFT OUTER JOIN ISTAT AS Istat_Vettore 
        ON Indirizzi_Vettore.pro_cod_istat = Istat_Vettore.PROV 
        AND Indirizzi_Vettore.com_cod_istat = Istat_Vettore.COM

    -- destinatario
    INNER JOIN Risorse_Umane as Risorse_Umane_Destinatario 
            ON Mov_Contabile.Cod_RisUm = Risorse_Umane_Destinatario.Cod_RisUm 
            
    INNER JOIN Contatti as Contatti_Destinatario 
        ON Risorse_Umane_Destinatario.Piva = Contatti_Destinatario.Piva 
        AND Risorse_Umane_Destinatario.Cod_Contatto = Contatti_Destinatario.Cod_Contatto 
    
    INNER JOIN Indirizzi AS Indirizzi_Destinatario 
        ON Mov_Contabile.Cod_IndirizzoRisUm = Indirizzi_Destinatario.cod_indirizzo 
    
    INNER JOIN ISTAT AS Istat_Destinatario 
        ON Indirizzi_Destinatario.pro_cod_istat = Istat_Destinatario.PROV 
        AND Indirizzi_Destinatario.com_cod_istat = Istat_Destinatario.COM 

    -- Codice Accisa  Destinatario
    LEFT JOIN Contatti_Codici AS Contatti_Codici_Destinatario_CodiceAccisa
        on Contatti_Codici_Destinatario_CodiceAccisa.PIVA = Contatti_Destinatario.Piva
        and Contatti_Codici_Destinatario_CodiceAccisa.Cod_Contatto = Contatti_Destinatario.Cod_Contatto
        and Contatti_Codici_Destinatario_CodiceAccisa.Id_cod = 4003
            
    -- destinatario diverso
    LEFT JOIN Risorse_Umane as Risorse_Umane_Destinatario_Diverso
            ON Mov_Contabile.Cod_Destinazione = Risorse_Umane_Destinatario_Diverso.Cod_RisUm 
            
    LEFT JOIN Contatti as Contatti_Destinatario_Diverso 
        ON Risorse_Umane_Destinatario_Diverso.Piva = Contatti_Destinatario_Diverso.Piva 
        AND Risorse_Umane_Destinatario_Diverso.Cod_Contatto = Contatti_Destinatario_Diverso.Cod_Contatto 
    
    LEFT JOIN Indirizzi AS Indirizzi_Destinatario_Diverso 
        ON Mov_Contabile.Cod_IndirizzoDestinazione = Indirizzi_Destinatario_Diverso.cod_indirizzo 
    
    LEFT JOIN ISTAT AS Istat_Destinatario_Diverso 
        ON Indirizzi_Destinatario_Diverso.pro_cod_istat = Istat_Destinatario_Diverso.PROV 
        AND Indirizzi_Destinatario_Diverso.com_cod_istat = Istat_Destinatario_Diverso.COM 

    -- Log MMV
    LEFT JOIN MVV_Log ON a.PIVA = MVV_Log.Piva 
        AND a.Id_Agenda = MVV_Log.Id_Agenda 
        
    WHERE a.Lav_Cod = 1071
    AND Mov_Contabile.Cau_Mov = '4000'
    AND Mov_Magazzino.Cau_Mov = '7350'

    AND Contatti_Codici_Speditore.Id_cod = 4003
    AND (Contatti_Codici_Speditore_CodMagazzino.Id_cod = 4006 and Contatti_Codici_Speditore_CodMagazzino.Val_cod <> '0')
    AND (Contatti_Codici_Speditore_UfficioSpedizioneImportazione.Id_cod = 4005)


GO

IF EXISTS (select 1 from sys.views where name = 'Agronica_Log_Contatti_UltimaOperazione')
    DROP VIEW [dbo].[Agronica_Log_Contatti_UltimaOperazione]
GO
CREATE VIEW [dbo].[Agronica_Log_Contatti_UltimaOperazione] AS
    WITH CTE AS (
        SELECT 
                  SuperUser, Utente, Chiave, Contatto_Des
                , Piva, Cod_Contatto, Sa_Cod, Id_Cf
                , Data_Ora_RegistrazioneLog, Note, Id_Servizio, Tipo_Operazione, Origine 
                , ROW_NUMBER() OVER (PARTITION BY Chiave ORDER BY Data_Ora_RegistrazioneLog DESC, ID DESC) AS NumeroRiga
        FROM [dbo].[Agronica_Log_Contatti]
    )

    SELECT UltimaAzione.SuperUser AS SuperUser
            , UltimaAzione.Utente
            , ISNULL(UltimaAzione.Chiave, '') AS Chiave
            , COALESCE(UltimaAzione.Contatto_Des, PenultimaAzione.Contatto_Des) AS Contatto_Des
            , UltimaAzione.Piva
            , UltimaAzione.Cod_Contatto
            , UltimaAzione.Sa_Cod
            , UltimaAzione.Id_Cf
            , UltimaAzione.Data_Ora_RegistrazioneLog
            , UltimaAzione.Note
            , UltimaAzione.Id_Servizio, 
    (CASE 
        WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_Operazione IS NULL THEN 1 --'INSERT'
        WHEN UltimaAzione.Tipo_Operazione = 1 AND PenultimaAzione.Tipo_Operazione = 3 THEN 2 --'MODIFICA'
        WHEN UltimaAzione.Tipo_Operazione = 2 THEN 2 --'MODIFICA DIRETTA'
        WHEN UltimaAzione.Tipo_Operazione = 3 THEN 3 --'DELETE'
        ELSE UltimaAzione.Tipo_Operazione
    END
    ) As UltimaOperazione, UltimaAzione.Origine
    FROM CTE UltimaAzione
    LEFT JOIN CTE PenultimaAzione 
        ON PenultimaAzione.Chiave = UltimaAzione.Chiave 
        AND PenultimaAzione.NumeroRiga = 2
    WHERE UltimaAzione.NumeroRiga = 1
GO

