-- Impostazioni utente 837 per memorizzazione statistiche, cambiato il modo in cui si memorizza se pivot o griglia

if  exists (
    select * from utenti_impostazioni where 
    (Impostazione_Valore_1 
    like '%"pivot":"false"%' and impostazione_cod = 837   ) or 
    (Impostazione_Valore_1 
    like '%"pivot":"true"%' and impostazione_cod = 837  )
)
begin
    UPDATE  utenti_impostazioni
    SET Impostazione_Valore_1 = REPLACE(Impostazione_Valore_1, '"pivot":"true"', '"tipoOutput":"Pivot"')
    where impostazione_cod = 837  

    UPDATE  utenti_impostazioni
    SET Impostazione_Valore_1 = REPLACE(Impostazione_Valore_1, '"pivot":"false"', '"tipoOutput":"Griglia"')
    where impostazione_cod = 837  
end
GO


-----------------------------------------------------------------
-- Forzo l'uso del nuovo modulo dei PDC/analisi per tutti (tranne chi ce l'ha già attivo e sta usando il vecchio)
-----------------------------------------------------------------
declare @Username as varchar(100)
set @Username = (SELECT  top 1 [Utente_Profilo] FROM Utenti_Profili Where [Utente] = [Utente_Profilo])

declare @PivaSuperUser as nvarchar(25)
set @PivaSuperUser = (select top 1 CodFisc from Utenti_Dettagli where UserName = @Username)

-- Per maggiore sicurezza escludo sia per username che per piva, così se uno dei due cambia sono coperta
IF (@Username IN ('apofruit','fruttagel','granfruttazani','greenyard','jingold','spreafico','terremerse','topfruitromagna')
    OR
    @PivaSuperUser IN ('00127740405','01271980391','00082340399','BE084760064','04030080404','00348240136','00069880391','02538910403'))
BEGIN
    PRINT('ESCLUSIONE Forzo utilizzo nuovo modulo PDC-ANALISI per ' + CAST(@Username as varchar(100)))
END
ELSE
BEGIN
    PRINT('Forzo utilizzo nuovo modulo PDC-ANALISI per ' + CAST(@Username as varchar(100)))
    IF NOT EXISTS (select 1 from utenti_impostazioni where [Impostazione_Cod] = 199)
        INSERT INTO utenti_impostazioni  
                    ([Username], Impostazione_Cod, [Impostazione_Valore_1],[Impostazione_Valore_2],[Impostazione_Valore_3], [Impostazione_Valore_4], Inviato, [Data_Creazione],[Data_Modifica],[Username_Creazione],[Username_Modifica],[Validita_Inizio],[Validita_Fine], [Piva_SuperUser])
        VALUES (@Username, 199, 1 ,'', '', '', 0,  getdate(), getdate(), 'agronica',  'agronica', cast(0x0000000000000000 as datetime),  cast(0x00011EC500000000 as datetime), @PivaSuperUser)
END
GO

