/* ----------------------------------------------------------------------------------------------------------- */
/* -------- QUERY DI UPDATE MAGAZZINI CONFERIMENTO IMPIANTO   --------------------- */
/* ----------------------------------------------------------------------------------------------------------- */

-- se ci sono impianti con impostato il magazzino conferimento
-- che hanno il val_cod che contiene ancora solo fabbricato_cod|sa_cod
if EXISTS  (
    select LEN(val_cod) - LEN(REPLACE(val_cod, '|', ''))
    from reg_impianti_codici
    where id_cod=1122
    and LEN(val_cod) - LEN(REPLACE(val_cod, '|', ''))=1
) 
begin


declare @e int
set @e = 0 


/* modifica il val_cod aggiungendo la piva che trova sull'organismo referente */
UPDATE [Reg_Impianti_Codici] 
  SET val_cod = val_cod + '|' + (
                                SELECT top 1 val_cod
                                FROM [Reg_Impianti_Codici] RIC
                                WHERE [Reg_Impianti_Codici].piva = RIC.piva
                                AND [Reg_Impianti_Codici].SA_COD = RIC.sa_cod
                                AND [Reg_Impianti_Codici].appezza = RIC.appezza
                                AND [Reg_Impianti_Codici].id_reg = RIC.id_reg
                                AND [Reg_Impianti_Codici].progetto_cod = RIC.progetto_cod
                                and id_cod=1074
                                )
WHERE ID_COD=1122
and LEN(val_cod) - LEN(REPLACE(val_cod, '|', ''))=1
set @e = @e + @@ERROR



if @e = 0
begin
    PRINT('*********** QUERY DI UPDATE MAGAZZINI CONFERIMENTO IMPIANTO OK *********************')

end
else
begin
    PRINT('!!!!! ERRORE: QUERY DI UPDATE MAGAZZINI CONFERIMENTO IMPIANTO NON ESEGUITO !!!!!!!!!!!')
end



end
GO

 

