--database server
declare @PivaSuperUser as char(25)
set @PivaSuperUser = (SELECT  top 1 [USER] FROM utentiximprese)

--select i.CODICE_FISCALE_TECNICO, t.*
update i
set CODICE_FISCALE_TECNICO = t.CF_tecnico 

from Reg_Impianti i
    inner join #t t
        on t.username = i.Username_Creazione collate SQL_Latin1_General_CP850_CI_AS
where  i.codice_fiscale_tecnico = ''
            or i.codice_fiscale_tecnico = '0'
            or codice_fiscale_tecnico is null
        
            
            
update i
set CODICE_FISCALE_TECNICO = t.CF_tecnico 

from Programmazione_Entita i
    inner join #t t
        on t.username = i.Username_Creazione collate SQL_Latin1_General_CP850_CI_AS
        and ( i.codice_fiscale_tecnico = ''
                or i.codice_fiscale_tecnico = '0'
                or codice_fiscale_tecnico is null
            )




