/* -------------------- [Mov_Dettaglio_Tecnico] ----------------------- */
/* ------------------------------------------------------------------------ */
 -- TODO Chiedere alla Fede
/* aggiornamento record concimazioni con Rame già salvate */
update Mov_Dettaglio_Tecnico
set cu=f.cu
from Mov_Dettaglio_Tecnico dt 
inner join Movimenti_dettagli d on dt.Id_Agenda=d.Id_Agenda and dt.Id_Mov=d.Id_Mov and dt.Id_Mov_Det=d.Id_Mov_Det and dt.piva=d.piva
inner join fertilizzanti f on f.Fer_Cod=d.pro_cod
where dt.cu=0
and elem_cod=3
and f.cu<>0
GO
  
   
   
