set W_Anagrafica_Stati_Cod=300
 from ricette_operazioni o 
inner join ricette r on r.ricetta_cod=o.ricetta_cod
inner join pua_testata p on  r.programmazione_cod = p.pua_cod and r.piva=p.piva
