IF  EXISTS (select * from PUA_Effluente  
    where (Data_Inizio_Divieto > '01/01/1900' or Data_fine_Divieto < '31/12/2100'))

    begin
        
        PRINT('sposto Divieti nella tabella PUA_Effluente_PeriodoDivieto')
        select * 
        into #PUA_Effluente_DivietiDaSpostare
        from PUA_Effluente  
        where (Data_Inizio_Divieto > '01/01/1900' or Data_fine_Divieto < '31/12/2100')

        insert into PUA_Effluente_PeriodoDivieto
        select 
            piva_superuser
            , DENSE_RANK() over (order by r.piva_superuser, r.id) + isnull((select max(id) from PUA_Effluente_PeriodoDivieto),0) as id
            , pua_cod
            , Regolamento_Cod
                   , id as ID_Pua_Effluente
                   ,Data_Inizio_Divieto
                   ,Data_Fine_Divieto
                   ,inviato
                   ,null
                   ,Data_Creazione
                   ,Data_Modifica
                   ,Username_Creazione
                   ,Username_Modifica
                   ,Validita_Inizio
                   ,Validita_Fine
        from #PUA_Effluente_DivietiDaSpostare r
        where not exists (
            select 1
            from PUA_Effluente_PeriodoDivieto i
            where r.piva_superuser = i.piva_superuser 
            and r.pua_cod = i.pua_cod and r.Regolamento_Cod = i.Regolamento_Cod
            and r.id = i.ID_Pua_Effluente
            )

        update PUA_Effluente  
        set Data_Inizio_Divieto = '01/01/1900', Data_fine_Divieto = '31/12/2100'
        where (Data_Inizio_Divieto > '01/01/1900' or Data_fine_Divieto < '31/12/2100')

        declare @MAX as int
        set @MAX = (select coalesce( max(Id),0)  from PUA_Effluente_PeriodoDivieto)

        if exists(select 1 from Sequenza_Tabelle where Nome_Tabella='PUA_Effluente_PeriodoDivieto')
        begin
         update Sequenza_Tabelle
         set Ultimo_Valore=@MAX
         where Nome_Tabella='PUA_Effluente_PeriodoDivieto'
        end
        else
        begin
            INSERT INTO Sequenza_Tabelle 
                (Nome_Tabella,Ultimo_Valore,Base,[End] ,inviato ,datainvio ,Data_Creazione ,Data_Modifica,Username_Creazione,Username_Modifica)
                VALUES
                ('PUA_Effluente_PeriodoDivieto',@MAX,0,2000000000,0,null,GETDATE(),GETDATE(),'script','script')
        end

        drop table #PUA_Effluente_DivietiDaSpostare

end
GO







